(function(root){'use strict';
var St=root.Store,U=root.UI,C=root.Calc,h=U.h;
function collect(today,allDates){
 today=today||C.today();var result=[],counts={};
 Object.keys(root.KD.defs).forEach(function(key){var def=St.def(key),rows=St.rows(key);counts[key]=rows.length;
  var dueFields=def.fields.filter(function(f){return f.type==='date'&&['due','deadline','payDue'].indexOf(f.k)>=0;});
  rows.forEach(function(r){if(r.done||r.status==='完了'||r.status==='今回は不要'||r.status==='入金済'||r.status==='取消'||r.stage==='納品済')return;
   dueFields.forEach(function(f){var d=r[f.k];if(!/^\d{4}-\d{2}-\d{2}$/.test(d||''))return;var n=Math.round((Date.parse(d+'T00:00:00Z')-Date.parse(today+'T00:00:00Z'))/86400000);if(allDates||n<=30)result.push({table:key,id:r._id,date:d,title:def.title,kind:f.label,days:n});});
  });
 });
 if(root.KD.shop&&root.KD.defs.products){var stock=root.KD.shop.stockMap();St.rows('products').forEach(function(p){if(p.code&&(stock[p.code]||0)<=C.num(p.reorder))result.push({table:'products',id:p._id,date:'',title:'在庫・発注点',kind:'商品コード '+p.code,days:null});});}
 if(root.KD.defs.craftMaterials)St.rows('craftMaterials').forEach(function(r){if(C.num(r.bought)-C.num(r.used)<=C.num(r.reorder))result.push({table:'craftMaterials',id:r._id,date:'',title:'材料の残量',kind:'材料ID '+r.code,days:null});});
 if(root.KD.defs.creatorStock)St.rows('creatorStock').forEach(function(r){if(C.num(r.incoming)-C.num(r.outgoing)<=C.num(r.reorder))result.push({table:'creatorStock',id:r._id,date:'',title:'紙の本・頒布在庫',kind:'作品ID '+r.work,days:null});});
 result.sort(function(a,b){return (a.days===null?999:a.days)-(b.days===null?999:b.days);});return {date:today,items:result,counts:counts};
}
function snapshot(){var s=collect(C.today(),true);return {format:'komorebi-workflow-summary-v1',edition:St.EDITION,generatedAt:new Date().toISOString(),date:s.date,counts:s.counts,attention:s.items.map(function(r){return {table:r.table,id:r.id,date:r.date,kind:r.days===null?'stock':r.days<0?'overdue':'due',days:r.days};})};}
function userPanel(s){var K=U.k,t=C.today(),plans=root.KD.defs.myPlans?St.rows('myPlans').filter(function(r){return !r.done&&(r.date===t||r.due===t);}):[],rest=s.items.filter(function(r){return !(r.table==='myPlans'&&plans.some(function(p){return p._id===r.id;}));});
 return h('div',{class:'today-plans'},plans.length?h('ul',{class:'plan-today'},plans.map(function(r){return h('li',null,h('span',{class:'plan-dot','aria-hidden':'true'}),h('span',null,r.title||K('（名前のない予定）','（なまえの ない よてい）')),r.due===t&&r.date!==t?h('span',{class:'small muted'},K('　今日まで','　きょうまで')):null);})):h('p',null,K('今日の予定はありません。ゆっくりで大丈夫。','きょうの よていは ありません。ゆっくりで だいじょうぶ。')),
 h('details',{class:'plan-more'},h('summary',{class:'btn small ghost'},K('予定の一覧を見る','よていの いちらんを みる')+'（'+rest.length+K('件）','けん）')),rest.length?U.miniTable([K('記録','きろく'),K('日付','ひづけ')],rest.slice(0,30).map(function(r){return [h('a',{href:'#'+St.def(r.table).mod},K(r.title,St.def(r.table).kanaTitle)),r.date];})):h('p',{class:'small muted'},K('近い予定はありません。','ちかい よていは ありません。')),h('p',{class:'small muted'},K('無理に急がなくて大丈夫。できるものから、自分のペースで。','むりに いそがなくて だいじょうぶ。できるものから、じぶんの ペースで。'))));}
function panel(){var s=collect();if(St.EDITION==='user')return userPanel(s);var late=s.items.filter(function(r){return r.days!==null&&r.days<0;}).length,stock=s.items.filter(function(r){return r.days===null;}).length;var week=s.items.filter(function(r){return r.days!==null&&r.days>=0&&r.days<=7;}).length;return h('div',null,h('ul',{class:'today-line'},h('li',{class:late?'attn':''},h('span',null,'期限超過'),h('strong',null,late+'件')),h('li',null,h('span',null,'7日以内'),h('strong',null,week+'件')),h('li',null,h('span',null,'在庫・材料不足'),h('strong',null,stock+'件'))),h('p',{class:'small muted'},late?'期限を過ぎたものから、ひとつずつ確認すれば十分です。':week?'今週の分だけ見れば十分です。':'急ぎの確認はありません。'),h('details',{class:'today-details'},h('summary',null,s.items.length?'30日以内の一覧を開く（'+s.items.length+'件）':'確認事項はありません'),root.Visuals.donut([{label:'期限超過',value:late},{label:'30日以内',value:s.items.length-late-stock},{label:'在庫・材料不足',value:stock}],function(n){return n+'件';}),s.items.length?U.miniTable(['記録','確認すること','期限','目安'],s.items.slice(0,100).map(function(r){return [h('a',{href:'#'+St.def(r.table).mod},r.title),r.kind,r.date||'—',r.days===null?'補充候補':r.days<0?'期限超過':r.days+'日後'];})):null,h('p',{class:'small muted'},'入力済みの期限と在庫から集計。最大100件を表示。元記録の追加・完了・帳簿転記は人が確認します。')));}

root.Workflow={collect:collect,snapshot:snapshot};
var previous=root.App.render;root.App.render=function(){previous();var main=root.document.getElementById('main');if(root.location.hash==='#home'||!root.location.hash){var card=U.card(St.EDITION==='user'?U.k('今日の予定','きょうの よてい'):'今日やること・期限が近いもの',{wide:true,cls:'today-card'},St.EDITION!=='user'&&root.KD.health?h('div',{class:'today-health'},root.KD.health.quick()):null,root.App.live(panel));var slot=root.document.getElementById('home-today');if(slot)slot.appendChild(card);else main.appendChild(card);}
 if(root.location.hash!=='#settings')return;
 main.appendChild(U.card('Driveへ渡す集計ファイル',{wide:true},h('p',null,'本文・氏名・金額を含めず、件数・行ID・期限・在庫注意だけをJSONにします。IDや期限にも業務情報が含まれるため、内容を確認して渡してください。これはローカル記録のバックアップではありません。'),h('button',{type:'button',class:'btn',on:{click:function(){var s=snapshot();U.ask('集計情報を保存しますか',h('div',null,h('p',null,'版：'+s.edition+'／注意事項：'+s.attention.length+'件'),h('pre',null,JSON.stringify(s,null,2))),[{label:'中止',value:false,tone:'ghost'},{label:'確認して保存',value:true}]).then(function(ok){if(ok)U.saveFile('komorebi-summary-'+s.edition+'.json',JSON.stringify(s,null,2),'application/json');});}}},'集計を確認して保存'),h('p',{class:'small muted'},'Driveへのアップロードは手動です。夜間処理は最後にアップした集計だけを読み、未送信の変更は取得できません。')));
 main.appendChild(U.card('AI・botの担当',{wide:true},h('p',null,'役割の例です。必要な担当だけ使えます。名前を分けても、AI側の権限や利用枠は分かれません。'),U.miniTable(['担当','このツールでの仕事'],Object.keys(root.KD_ASSIST_ROLES).map(function(k){var r=root.KD_ASSIST_ROLES[k];return [r.name,r.role];})),h('p',null,'ローカル直接接続は無効。元依頼と変更案を照合し、人が差分を承認する受入口を使います。')));
};
// Refresh derived panels after returning to the page; never save or send records on a timer.
root.document.addEventListener('visibilitychange',function(){if(!root.document.hidden&&root.location.hash==='#home')root.App.render();});
})(this);

this.KD_DESK_CATALOG=[{"id":"DOT-001","title":"生活請求トレイ","group":"生活","fields":["請求の場所","請求額","支払方法の確認先","変更依頼日","初回引落の確認"],"proposal":"提案：支払う側の「生活請求トレイ」。請求書の場所・金額確認・支払操作・支払確認を別状態で管理する。転居や口座変更時は「変更依頼→初回引落確認」の工程を追加。保留中は次の一手だけ残し、送金・自動決済はしない。","boundary":"支払済みの誤認、督促の圧迫感、金融情報の露出。口座番号や認証情報を要求せず、サービス名と確認状態だけでも使える。"},{"id":"DOT-002","title":"書類の受取から受理まで","group":"生活","fields":["書類名","必要な物","提出先","受取日","提出日","受理または差戻し"],"proposal":"提案：書類名・必要物・対象タグと、受取→記入→本人確認→提出→受理／差戻しを一つのケースで管理。止まる理由と次の一手を表示し、同じ学校通知は束ねる。実名や書類画像は不要。","boundary":"資格判定・代理提出をしない。実名、健康調査、家庭事情、身分証を取り込まない。家族間同期や受理の自動認証をうたわない。"},{"id":"DOT-003","title":"休養日入り資金計画","group":"休息","fields":["守る固定費","生活費の前提","確定入金","未確定案件","休養日"],"proposal":"提案：「守る固定費・生活費」と本人が選ぶ休養日を置いた資金カレンダー。確定入金／未確定案件と低・通常・高稼働の手入力条件を分け、不足する日・未確認支出を示す。細目入力なしの表示も選べる。","boundary":"資金安全・使ってよい確定額・給付資格・就労能力を保証しない。家族の監視や支出制限に転用せず、資産情報は不要な初期設計にする。"},{"id":"DOT-004","title":"議題と決定の記録","group":"段取り","fields":["議題","担当役","完了条件","決定か提案か","未決事項"],"proposal":"提案：依頼・議題カードに担当、期限、完了条件と「決定済み／提案／確認待ち」を記録。議題に結論を追記して議事録を印刷し、未決だけ次回へ繰越。空欄を聞く短文は本人が確認する。","boundary":"合意していない約束を生成せず、異論や未決意見を削らない。機密情報の持込み規則を確認。自動受信・送信はしない。"},{"id":"DOT-005","title":"相手別の開示メモ","group":"連絡","fields":["宛先の役割","伝える目的","伝える作業","必要な配慮","今回は伝えないこと"],"proposal":"提案：宛先と目的ごとに作業・期限・連絡方法・必要な配慮等を本人が選び、伏せ字付きで出力前確認。今回選ばない項目を明示し、前の相手への開示範囲を自動継承しない。","boundary":"無断開示・自動共有をしない。出力後の回収を保証せず、暗号ロックを相手別権限制御と混同しない。受領状態は手動記録と明示。"},{"id":"DOT-006","title":"準備・移動込みの予定","group":"段取り","fields":["変更前の予定","変更後の予定","準備時間","移動時間","費用上限","変更期限"],"proposal":"提案：変更前後の予定に本人入力の準備・移動時間を重ね、重複と余白不足を表示。代替移動の費用上限・変更期限を付けたA/B案と、手動相談用の候補表を作る。","boundary":"位置情報・通院先を自動収集しない。健康判断・勤務受諾・予約取消・ルートの安全性判定を自動実行しない。"},{"id":"DOT-007","title":"休止と再開のカード","group":"休息","fields":["どこまで終えたか","資料の所在","休止による影響","判断を頼む相手","未発送・支払確認","再開前に確かめること"],"proposal":"提案：平時に準備する「休止・再開カード」。未完了、資料の所在、期限影響、判断を頼む相手、未発送、発注・支払い確認を集め、再開前チェックまで一続きにする。必要項目だけを連絡下書きへ。","boundary":"休む本人に大量入力を強制しない。病名不要。一括取消、発注・支払い停止、送信、担当割当を自動実行せず、再開日を保証しない。"},{"id":"DOT-008","title":"再開しおり","group":"休息","fields":["ここまで完了","次にする一手","参照資料の位置","確認待ち"],"proposal":"提案：「再開しおり」。どこまで完了・次の一手・参照資料の位置を一行ずつ保存し、再開時はそこから確認。未完了・確認待ち・完了を混在させない。","boundary":"記録作業自体が中断負担になる。医療・運転・危険作業の安全管理代替として販売しない。"},{"id":"DOT-009","title":"受診前の質問整理","group":"生活","fields":["勤務時間","通勤","仕事内容","困る場面","聞きたい質問","まとめに含めないこと"],"proposal":"提案：既存の医師向け月間まとめを拡張し、勤務時間・通勤・仕事内容・困る場面・聞きたい質問を本人が追加選択する。31件・80文字制限で省略される情報を明示し、出力前編集を可能にする。","boundary":"医師の意見書・診断書を自動生成しない。病名や勤務内容の誤記、省略の見落とし、不要開示に注意。"},{"id":"DOT-010","title":"相談ルートメモ","group":"生活","fields":["相談したいこと","地域の公式窓口","情報確認日","問い合わせ結果","次の紹介先"],"proposal":"提案：相談ルートメモ。地域の公式窓口URL・確認日・相談したいこと・問い合わせ結果・次の紹介先を一件にまとめ、たらい回しで説明が消えないようにする。自動適格判定はしない。","boundary":"古い電話番号・対象条件で誤案内しない。相談メモの開示は本人が選択、病歴の自動送信はしない。"},{"id":"DOT-011","title":"生活支援の引継ぎ地図","group":"支援","fields":["本人の希望","今の担当役","一時不在時の代替","長期不在時の候補","費用の前提","未相談事項"],"proposal":"提案：本人参加の「生活支援・引継ぎ地図」。食事・買物等の実務ごとに本人の希望、今の担当、一時不在時の代替、長期不在時の候補、費用目安、未相談事項、更新日を整理する。必要部分のみ印刷し、依頼は手動にする。","boundary":"家族の記録で本人の意思を上書きせず、役割や依頼を自動確定しない。現行は認証・役割分離がないため共同編集や閲覧保証をうたわない。医療・介護の代替としない。"},{"id":"DOT-012","title":"暮らしの収支前提比較","group":"生活","fields":["住まいの希望","サービス利用の前提","家族支援の有無","確定した給付","未確認費用"],"proposal":"提案：生活費の前提比較ノート。本人の希望する住まい・利用予定サービス・家族支援の有無で、入力した収支の複数案を比較し、「未確認の費用」を残す。給付は確定額と未確認を分ける。","boundary":"資産運用や受給可否を勧めない。長期予測を確定値にせず、資産情報は任意。家族の価値観で本人の生活を制限しない。"},{"id":"DOT-013","title":"文字で確認する連絡","group":"連絡","fields":["日時の原文","金額の原文","場所","聞き取れなかった点","文字で確認する短文","代替連絡手段"],"proposal":"提案：「文字で確認する連絡ノート」。日時・金額・場所・次の行動と聞き取れなかった箇所を分け、文字で確かめる短文を作る。本人が確認した代替連絡手段と確認日も任意登録し、返答待ちと確定を区別する。","boundary":"本人確認の迂回やなりすましをしない。録音を要求せず、推測を確定値に補完しない。緊急通報や医療指示確認の代替をうたわない。"},{"id":"DOT-014","title":"使いやすさの実機点検","group":"データ","fields":["試す操作","使用機器と支援技術","保存状態の確認","フォーカスの戻り先","失敗した箇所","再確認日"],"proposal":"提案：保存・検索・ロック解除・エラー・出力まで、読み上げとキーボード等で完走できるよう検証する。ボタン名・状態変化・見出し・フォーカス復帰を整え、「保存済み／失敗／未完了」は文字等で後から確認可能にする。説明も同じ支援技術で読める形式にする。","boundary":"診断名でUIを固定しない。通知に本文を載せず、点滅・音声を強制しない。保存失敗時の検索漏えいR54と読み上げの整合を最優先。"},{"id":"DOT-015","title":"受注前の条件比較","group":"仕事","fields":["通常案","範囲縮小案","分割納品案","納期調整案","返信可能帯","中断時の連絡方法"],"proposal":"提案：受注前の条件比較カード。通常／範囲縮小／分割納品／納期調整を本人設定の時間上限・金額・返信可能帯・中断時の連絡方法で比較。追加料金は本人設定で、病名や家庭事情は出力しない。","boundary":"就労能力や契約の有効性・法令適合・請求可否を判定しない。睡眠削減を勧めず、自動契約・合意・送信をしない。"},{"id":"DOT-016","title":"取引先の継続相談","group":"仕事","fields":["取引先の仮ID","試作・見積・継続の段階","次回相談日","予定数量","受注上限","一社依存の確認"],"proposal":"提案：取引先ごとに試作→見積→継続の段階、次回相談日、予定数量と本人設定の受注上限を手入力。少数の連絡候補と不足月・一社依存を見せ、連絡下書きは本人が作成・確認する。","boundary":"売上予測や関係性の自動採点をしない。連絡先・健康事情を漏らさず、自動DM・投稿・営業送信をしない。"},{"id":"DOT-017","title":"仕事量と採算の比較","group":"仕事","fields":["メニューの範囲","材料費","移動・待機","実作業時間","件数削減案","簡素化案"],"proposal":"提案：仕事・メニューごとの報酬、材料、移動・待機・実作業時間を使い、本人設定の時間上限内で件数削減・品数削減・内容簡素化を比較。店種別に仕込みまたは予約枠への影響を表示する。","boundary":"概算利益・集客・健康効果を保証しない。運転中操作を促さず、自動配車や衛生法定管理の代替にしない。過去単価を上書きしない。"},{"id":"DOT-018","title":"材料価格の変更影響","group":"商い","fields":["材料の仮ID","旧価格","新価格","価格確認日","影響作品","代替材料案"],"proposal":"提案：材料価格の変更影響カード。材料の旧価格・新価格と更新日を残し、影響作品、価格据置時の差、代替材料案を一覧化する。外部価格の自動取得はしない。","boundary":"販売済み商品の原価を新価格で上書きしない。推奨価格ではなく比較値として表示。"},{"id":"DOT-019","title":"休息を守る受付上限","group":"休息","fields":["週の上限","先に確保する休息","引受済み工数","候補の工数","候補か合意済みか","振替期限"],"proposal":"提案：本人が週上限・休息枠・工数／負荷を設定し、受ける前に残枠と連続負荷を確認。教室では振替対象・期限と候補／合意済みを併記し、作家は梱包工数、サロンは休憩・終了時刻を反映。確定は手動。","boundary":"健康から受注可否・適正量を算出しない。病名・家庭事情は不要。自動排除、予約移動、EC在庫変更、送信はしない。手動確認は認証済み既読ではない。"},{"id":"DOT-020","title":"小さな試作と改善","group":"仕事","fields":["誰に届けるか","仮説","価格以外の変更","必要設備","試す期間","時間・予算上限","中止条件"],"proposal":"提案：試作・販売改善カードに「誰向け／仮説／価格以外の変更／必要設備／少数の対象品／期間／時間・予算／中止条件」を記録。結果と本人の感想を分け、次の小さな試行を人が決める。","boundary":"売上や工賃向上を保証せず、不安を点数化・診断しない。設備購入や外部販売を自動実行しない。"},{"id":"DOT-021","title":"追加修正の合意メモ","group":"仕事","fields":["当初の範囲","依頼された変更","追加見積時間","追加額","相手の回答","期限への影響"],"proposal":"提案：修正予算・合意メモ。初期範囲、依頼変更、本人見積時間、追加額、相手回答を時系列で残し、期限と余白への影響を見せる。","boundary":"法違反・責任・請求可能額を自動判定しない。記録の証拠能力を保証せず、外部送信は本人確認。"},{"id":"DOT-022","title":"取消時点の控え","group":"仕事","fields":["取消連絡日","制作の進捗","実作業時間","確保した枠","受領資料の所在","確認待ち"],"proposal":"提案：取消時点スナップショット。取消連絡日、準備・制作の進捗、実作業時間、確保枠、受領資料の所在、確認待ち事項を凍結表示し、再受注計画と分ける。","boundary":"補償請求・責任追及文は自動作成しない。法的証拠保全の代替と宣伝せず原本保管を分ける。"},{"id":"DOT-023","title":"まとめ発送デイ","group":"商い","fields":["発送締切","一日の梱包上限","資材準備","梱包パターン","案内する発送日"],"proposal":"提案：まとめ発送デイ。発送締切と本人設定の1日梱包上限、資材の下準備、梱包パターンを並べ、受付時に案内する発送日文案を作る。","boundary":"配送日や到着日を保証しない。配送会社のAPI・EC投稿・購入者連絡は自動化しない。"},{"id":"DOT-024","title":"配送トラブルの別箱","group":"商い","fields":["元注文の仮ID","連絡待ち","返送到着","再梱包","追加費用","返金と再送の区別"],"proposal":"提案：配送トラブル別箱。元注文、連絡待ち、返送到着、再梱包、追加費用、本人の次の1手をまとめる。元売上と返金・再送の状態を分ける。","boundary":"返金・再発送・補償申請は自動実行しない。個人情報は最小限にし外部保存なし。"},{"id":"DOT-025","title":"事実と見立てを分ける記録","group":"支援","fields":["観察した事実","本人の言葉","職員の見立て","実施した対応","確認した結果"],"proposal":"提案：観察した事実／本人の言葉／職員の見立て／対応／結果を分ける入力補助。抽象語には「何が見えた？」と任意の確認を出す。","boundary":"事実を自動補完しない。医学的判定や本人へのレッテル貼りをしない。"},{"id":"DOT-026","title":"支援手順の条件カード","group":"支援","fields":["作業工程","本人のみ・声かけ・一部介助","実際の言い方","待つ時間","環境","本人の希望"],"proposal":"提案：場面と作業工程ごとに本人だけで実施／声かけ／一部介助、実際の言い方、待つ時間、環境、本人希望、見直し日を分ける手順カード。前回との条件差を並べ、一般的な練習例から試す。","boundary":"能力ランキング・自動選別に使わず本人の希望・拒否を保持。児童動画や診断詳細は扱わず、権限分離のない校内・施設内共有基盤にしない。"},{"id":"DOT-027","title":"CSV列対応と件数照合","group":"データ","fields":["取込元の列","取込先の列","施設内仮ID","期待件数","取込件数","日別合計の差"],"proposal":"提案：既存CSVに列対応表・施設内ID照合・件数／日別合計の差分プレビューを追加。取込先仕様ごとに再利用できる変換設定を保存。","boundary":"公的様式・請求データとしての適合を保証しない。外部送信は手動承認。CSV数式注入対策が必要。"},{"id":"DOT-028","title":"工程と役割の組替え","group":"支援","fields":["工程","道具","見本の所在","説明形式","希望時間","必要な支援","引継ぎ先"],"proposal":"提案：受注作業・施設業務を工程カードに分け、道具・見本・説明形式・希望時間・必要な支援を並べる。本人と担当者が手動で組替え、引継ぎ先や担当が決まらない役割だけ表示する。","boundary":"障害名や能力点で自動配属せず、家族事情は不要。安全な体制・法定配置充足を保証せず、本人と担当者が決める。"},{"id":"DOT-029","title":"匿名の一枚営業資料","group":"仕事","fields":["対応業務","品質確認工程","納期目安","受付条件","掲載してよい範囲"],"proposal":"提案：対応業務・品質確認工程・納期目安・受付条件だけから、匿名の一枚営業資料を印刷。公開前に掲載可否チェックを置く。","boundary":"顧客成果物・ロゴ・写真の権利確認が必要。利用者の病名や個人実績を無断掲載しない。"},{"id":"DOT-030","title":"見積の根拠メモ","group":"仕事","fields":["対象数量","仕様","材料","移動","検品","準備時間"],"proposal":"提案：案件別の材料・移動・検品・職員の準備時間を分けた見積根拠メモ。数量や仕様を変えた複数案を比較し、交渉用一枚を印刷。","boundary":"会計・税務判断や適正価格を自動断定しない。利用者の価値を生産性だけで評価しない。"},{"id":"DOT-031","title":"製作手順の版管理","group":"商い","fields":["工程","治具","失敗例","品質確認点","更新者の役割","旧版との違い"],"proposal":"提案：商品ごとの工程・治具・失敗例・品質確認点・更新者を端末内に保存。担当交代時に旧版と現行版を比較して引継ぎ印刷。","boundary":"食品・機械等の安全手順を自動生成しない。専門職が承認した手順を登録する。"},{"id":"DOT-032","title":"工賃と別軸の面談","group":"支援","fields":["本人が選ぶ目標","負担","通いやすさ","満足した活動","作業の用途","本人の感想"],"proposal":"提案：本人が選ぶ目標・負担・通いやすさ・満足した活動を、工賃と別軸で振り返る面談カード。作業の用途をやさしい言葉で付記し、匿名の納品後反応や本人の感想を任意で残す。","boundary":"回答強制、達成点数化、利用制限、診断・治療評価に使わない。顧客機密を露出せず、感謝や感想を捏造しない。"},{"id":"DOT-033","title":"採用経路の振り返り","group":"支援","fields":["経路の区分","応募数","面接数","入職数","在籍確認期間","少数区分を伏せる基準"],"proposal":"提案：採用経路別に応募・面接・入職・一定期間後の在籍を集計。小数人数は非表示にし、個人名なしで採用施策を振り返る。","boundary":"採用・解雇の自動評価に使わない。小規模集計で個人が推測されないようにする。"},{"id":"DOT-034","title":"制度・研修から役割へ","group":"支援","fields":["利用できる制度","相談先","研修の所在","目指す役割","情報確認日"],"proposal":"提案：職員向けに利用できる制度・相談先・研修から役割への道筋を一枚マップにする。更新日と確認先を明示して印刷可能に。","boundary":"就業規則や給付資格の判定を代替しない。古い制度を現行として表示しない。"},{"id":"DOT-035","title":"チーム改善の振り返り","group":"支援","fields":["改善テーマ","実施した工夫","確認できた変化","未解決点","次の確認"],"proposal":"提案：チームが選んだ改善テーマに、実施した工夫・確認できた変化・未解決点を紐付ける月次振り返り。個人順位はつけない。","boundary":"支援成果を施設の宣伝に無断転用しない。利用者の変化を職員の点数に短絡しない。"},{"id":"DOT-036","title":"業務継続の机上訓練","group":"支援","fields":["想定する不在","残る職員役","継続する業務","止める業務","応援へ渡す業務","代替未定"],"proposal":"提案：想定別に「残る職員役・継続する業務・止める業務・応援へ渡す業務」を切替える机上訓練ボード。代替担当未定を可視化。","boundary":"安全な配置・避難・医療対応の判断を代替しない。職員の居場所を常時追跡しない。"},{"id":"DOT-037","title":"紙へ切替える手順パック","group":"データ","fields":["必要な手順","物品の所在","連絡順","共通位置番号","更新日","紙での変更","復旧後の反映確認"],"proposal":"提案：必要最小限の手順・物品所在・連絡順または教材を、更新日と共通位置番号付きで紙へ切り替えるパック。最新版・再開位置を確認し、復旧後に紙での変更を反映する模擬手順を付ける。","boundary":"紙も漏えいするため最小項目、保管・回収を設計。防災・避難判断や学習効果を保証せず、既存オフラインを新機能扱いしない。"},{"id":"DOT-038","title":"発表会の進行台帳","group":"学び","fields":["曲目ID","演奏時間","転換時間","休憩時間","準備締切","提出状況"],"proposal":"提案：曲目ID、演奏・転換・休憩時間、準備締切と提出状況を一体化した発表会台帳。並べ替えで終了予定を再計算し、司会用進行表と未完了チェックを印刷。前年の反省は次回項目へ手動で取り込む。","boundary":"児童名は仮IDで検証。同意書の実物・署名は保存しない。予定計算で当日の進行を保証しない。"},{"id":"DOT-039","title":"授業報告と未解決事項","group":"学び","fields":["授業の事実","講師の所見","報告への質問","確認待ち","次回対応"],"proposal":"提案：授業の事実を報告書下書きへ差し込み、所見と区別。報告ごとの質問・確認待ち・次回対応を手動で紐付け、面談では未解決事項を印刷する。未記録の成果は補完しない。","boundary":"児童の能力・進路の自動判定をしない。家庭事情の蓄積、外部AI送信、自動返信をしない。"},{"id":"DOT-040","title":"教材の制作・配付票","group":"学び","fields":["教材版","完成見本","配付先の区分","人数","予備","サイズと加工","受渡し確認"],"proposal":"提案：教材版・完成見本・配付先区分・人数・予備・サイズ・加工・納期を一枚の制作票に統合。総枚数と仕分け札を出し、旧版混在を注意表示。受渡し・完成確認は手動記録する。","boundary":"プリンタを直接操作せず、利用者が確認。未許諾教材の複製を含めず、共有権限・実児童情報は扱わない。"},{"id":"DOT-041","title":"やさしい日本語の編集票","group":"学び","fields":["原文の所在","行動する人","期日","場所","持ち物","用語の説明","確認した本文"],"proposal":"提案：行動主・期日・場所・持ち物を確認し、学校用語の短い説明を添えられるやさしい日本語本文編集シート。原文対照、ふりがな、短文・分かち書きを人が確認し、未記載事項は推測しない。","boundary":"国籍から能力を推定しない。日時や持参物を推測せず、内容と変換の正確性は人が確認する。"},{"id":"DOT-042","title":"読みやすい教材のひな形","group":"学び","fields":["教材の目的","文字サイズ","余白","選択肢数","絵と文字の比率","印刷確認"],"proposal":"提案：匿名の教材目的だけを入力し、文字サイズ・余白・選択肢数・絵と文字の比率を変えて印刷できるテンプレート。子どもの診断に基づく自動最適化はしない。","boundary":"医療・発達評価や能力分類をしない。児童記録を入力せず、支援の有効性も保証しない。"},{"id":"DOT-043","title":"バックアップの世代点検","group":"データ","fields":["世代名","作成日","内容一覧","復元試験日","別媒体の保管確認"],"proposal":"提案：既存バックアップに世代・作成日・内容一覧・復元テスト日を表示し、引き継ぎ前の模擬復元チェックを案内。別媒体保管を利用者が実施したか手動確認できるようにする。","boundary":"生徒名簿のUSB持出しを推奨しない。暗号化だけで共有権限・学校規則を満たすとはしない。"},{"id":"DOT-044","title":"送迎の降車・引渡し確認","group":"支援","fields":["便の仮ID","乗車予定との差","実乗車","降車","引渡し","車内の実見確認"],"proposal":"提案：便IDごとに乗車予定との差、実乗車、降車・引渡し、車内の実見確認を一枚で照合。未確認者と車内確認未了を残し、到着時刻だけで便を完了扱いにしない。","boundary":"単独担当・端末内仮IDの架空モック限定。画面操作を実見確認の代わりにしない。検知・自動点呼・安全保証なし。導入前に送迎安全担当が検証。"},{"id":"DOT-045","title":"献立選択と伝達の照合","group":"支援","fields":["献立候補","回答の状態","厨房への伝達確認","締切後の変更","未反映件数"],"proposal":"提案：献立候補を仮ID別に選び、未回答・選択済み・厨房へ伝達確認済みを分ける。締切後は変更分だけを照合し、確定数量と未反映件数を印刷する。発注送信はしない。","boundary":"単独担当・端末内仮IDの架空モック限定。アレルギー・食形態・栄養条件を推定しない。専門職が承認した選択肢だけを使う。"},{"id":"DOT-046","title":"食事便の受取・保留票","group":"支援","fields":["便の仮ID","確認した温度と時刻","保管場所","提供・保留・返却","承認済み手順の所在"],"proposal":"提案：食缶・便IDに受取状態、確認した温度・時刻、保管場所、提供・保留・返却を記録。施設の承認済み手順との差を示し、判断待ちの食品を通常提供一覧と分ける。","boundary":"単独担当・端末内仮IDの架空モック限定。自動の喫食可否判定や温度基準生成は禁止。衛生責任者が最新手順・対象設備を確認する。"},{"id":"DOT-047","title":"食材ロットの逆引き","group":"支援","fields":["仕入ロット","使用日","献立ID","残数","回収連絡の所在","人が確認した範囲"],"proposal":"提案：仕入ロット・使用日・献立ID・残数を手動で結び、指定ロットから対象の食事日と未使用分を逆引き。回収連絡の原文所在と、人が確認した対応範囲を一枚にまとめる。","boundary":"単独担当・端末内仮IDの架空モック限定。個人の健康影響・回収要否は自動判定しない。保存期間と連絡先は施設・専門家が確認。"},{"id":"DOT-048","title":"食卓セットの準備","group":"支援","fields":["用具の仮ID","配置図の所在","専門職の確認先","不足品","再確認日"],"proposal":"提案：本人と専門職が確認した机・椅子・食器・自助具のIDと配置図を『食卓セット』として保存。席替えや洗浄後は必要品の不足だけ確認し、適合の再判断は専門職へ残す。","boundary":"単独担当・端末内仮IDの架空モック限定。姿勢・嚥下・用具の適合は推定しない。顔・身体画像は保存せず、構成図を使う。"},{"id":"DOT-049","title":"衣類袋の受渡し照合","group":"支援","fields":["衣類袋の仮ID","回収数","業者受渡し数","返却数","本人への返却数","保留差分"],"proposal":"提案：匿名の衣類袋IDで回収数、業者受渡し、返却数、本人へ戻した数を照合。差分だけを保留し、家族の持込み・持帰りも同じ台帳で増減する。全衣類の撮影は必須にしない。","boundary":"単独担当・端末内仮IDの架空モック限定。衣類の価値を自動算定しない。私物写真の一括保存を避け、弁償や家族連絡は人が確認。"},{"id":"DOT-050","title":"浴槽と次枠の準備","group":"支援","fields":["浴槽の仮ID","準備・使用・片付け","必要な用具","着替えとタオル","仕切り","次枠確認"],"proposal":"提案：浴槽ごとに準備・使用中・片付け・次枠準備済みを表示。決定済み用具、着替え、タオル、仕切りを確認してから次枠を案内し、待ち時間は集計だけ残す。","boundary":"単独担当・端末内仮IDの架空モック限定。入浴可否・方法・介助配置を自動決定しない。裸身画像や個人名の公開表示なし。"},{"id":"DOT-051","title":"環境調整を試すノート","group":"支援","fields":["本人が困る場面","合意した変更","試す期間","元に戻す条件","変更後の実感","観察した事実"],"proposal":"提案：場所・時間帯・音・照明・作業量等の環境調整ノート。本人の困る場面、合意した変更、試す期間、元に戻す条件、変更後の実感と観察を対照する。継続・変更・中止は手動で決め、診断や機器推薦はしない。","boundary":"単独担当・端末内仮IDの架空モック限定。録音や人物監視を行わない。静かな部屋への隔離・移動を自動提案しない。本人参加で見直す。"},{"id":"DOT-052","title":"移動と設備配置の比較","group":"支援","fields":["移動区間","待合い場所","同時利用の設備","本人が選べる場所","時間をずらす案","配置の比較"],"proposal":"提案：施設内の移動区間、待合い場所、同時に使う設備を簡易配置図で確認。本人が選べる待機場所を残し、時間のずらし方や設備配置のA/B案を人が比較する。","boundary":"単独担当・端末内仮IDの架空モック限定。人数上限や避難安全を自動判定しない。本人の移動を制限する目的に使わない。配置は専門家確認。"},{"id":"DOT-053","title":"用具セットの貸出点検","group":"支援","fields":["セットの仮ID","構成品","受渡し","返却照合","点検と補充","再使用の確認"],"proposal":"提案：本体・付属品・消耗品を一組で登録し、受渡し／使用、返却照合、点検・補充待ち、再使用可を管理するセット台帳。期限や構成品が未確認なら準備済みにせず、不具合は故障管理へ渡す。","boundary":"単独担当・端末内仮IDの架空モック限定。利用者の適合や安全を保証しない。福祉用具は専門担当が点検し、写真や個人情報を最小化。"},{"id":"DOT-054","title":"設備・私物の維持管理","group":"支援","fields":["物品の仮ID","手順の所在","点検","使用停止と保管","代替","補修結果","再使用確認"],"proposal":"提案：設備・私物IDに承認済み手順、点検、使用停止・保管、代替、補修依頼、結果、再使用確認を結ぶ維持管理票。車両装置・衣類・季節機器の項目を切替え、私物の処分は本人の希望確認なしに決めない。","boundary":"自動で使用再開・廃棄・修理方法を決めない。機器別の承認手順と有資格者の確認が前提。所有物の決定権を尊重し、鍵・住所等を保存しない。"},{"id":"DOT-055","title":"鍵と閉館の引継ぎ","group":"支援","fields":["匿名管理番号","未返却または紛失","対象区域","閉館の実見","責任者への引継ぎ","未確認事項"],"proposal":"提案：鍵を匿名管理番号で扱い、未返却・紛失の申告、対象区域、閉館実見、責任者への引継ぎを一件化。紛失時の利用継続・交換等は確認待ちで保持し、鍵の複製や交換は行わない。","boundary":"単独担当・端末内仮IDの架空モック限定。鍵形状・暗証番号・解除方法は保存しない。実鍵操作や警備設定変更なし。避難・外出を妨げる運用にしない。"},{"id":"DOT-056","title":"部屋の標準配置へ戻す","group":"支援","fields":["部屋の仮ID","標準備品","配置見本","一時変更","戻した物","未復旧箇所"],"proposal":"提案：部屋ごとの標準備品・配置見本と、活動用の一時変更を対照。終了時に戻した物と未復旧箇所を記録し、次の利用前の準備票へ差分だけ渡す。","boundary":"単独担当・端末内仮IDの架空モック限定。配置図は仮図だけで試す。通路幅・車いす動線や避難安全の自動認定はしない。"},{"id":"DOT-057","title":"分別と収集の確認","group":"支援","fields":["公式案内の所在","確認日","施設の分別区分","保管場所","収集方法","未判定品"],"proposal":"提案：所在地の公式案内の確認日、施設で決めた分別区分、保管場所、収集方法をカード化。迷う品目は未判定のまま確認先へ残し、排出済み・収集未了を分ける。","boundary":"単独担当・端末内仮IDの架空モック限定。危険物・感染性廃棄物を自動分類しない。最新の地域規則と専門業者へ確認。廃棄実行なし。"},{"id":"DOT-058","title":"用具の用途と洗浄状態","group":"支援","fields":["用具の仮ID","用途区分","収納位置","使用後の洗浄","乾燥","収納確認"],"proposal":"提案：まな板・容器・シンク等に施設の用途区分と収納位置を付け、準備時に用途、使用後に洗浄・乾燥・収納状態を照合。色だけに頼らず文字や記号を併記する。","boundary":"単独担当・端末内仮IDの架空モック限定。消毒剤や濃度・加熱条件を自動案内しない。衛生責任者が現行手順を登録し、実物確認を置換しない。"},{"id":"DOT-059","title":"接触箇所の清掃点検","group":"支援","fields":["場所の仮ID","接触箇所","清掃範囲","確認日","作業状態","点検漏れ"],"proposal":"提案：室名だけでなく手すり・スイッチ等の接触箇所を仮配置図に登録し、通常清掃の範囲と確認日を表示。未着手、作業済み、確認待ちを区別し、点検対象の抜けを見直す。","boundary":"単独担当・端末内仮IDの架空モック限定。清掃済みを感染リスクゼロと表示しない。薬剤・頻度は専門担当が決める。個人の病状は記録しない。"},{"id":"DOT-060","title":"区域の再利用確認","group":"支援","fields":["場所の仮ID","立入り調整","担当への引継ぎ","影響物品","処理完了","再利用の人による確認"],"proposal":"提案：人名ではなく発生場所に区域カードを作り、立入り調整、処理担当への引継ぎ、影響物品、処理完了、再利用の人による確認を残す。通常清掃とは別の未終了一覧にする。","boundary":"単独担当・端末内仮IDの架空モック限定。画面を見て処理を遅らせない。薬剤配合・感染判定・自動解除なし。現場の衛生責任者が監修。"},{"id":"DOT-061","title":"場所ごとの再発点検","group":"支援","fields":["場所の仮ID","目撃日","点検箇所","専門調査の所在","実施した物理的対策","次の確認"],"proposal":"提案：匿名の場所IDに目撃日、点検箇所、業者調査の結果所在、実施した物理的対策、次の確認を重ねる。個体同定や薬剤判断はせず、再発地点の推移だけを見る。","boundary":"単独担当・端末内仮IDの架空モック限定。生物種・駆除要否・薬剤を自動判定しない。場所は仮図で試し、実施は専門家判断。"},{"id":"DOT-062","title":"試す前後の希望比較","group":"支援","fields":["本人が知りたい条件","少し試す方法","負担上限","中止と戻し方","説明で聞いたこと","試したこと","未確認"],"proposal":"提案：本人が知りたい条件、少し試す方法、負担上限、中止・戻し方を置く体験比較票。説明で聞いたこと／本人が試したこと／未確認を分け、体験前後の希望を比較する。試さない・選び直す選択も残す。","boundary":"試行を実質的な強制にしない。重大な危険の判断は専門職へ委ね、ツールは可否判定しない。"},{"id":"DOT-063","title":"意思確認と撤回の履歴","group":"支援","fields":["目的","対象と範囲","同意・断る・保留・別案・撤回","本人の希望する見直し","目的変更"],"proposal":"提案：支援の目的・対象・範囲と、同意／断る／保留／別案／撤回を結ぶ意思確認履歴。未回答を同意へ変えず、理由の入力も強制しない。目的変更時は再確認待ちにし、本人が望む時だけ見直す。法的有効性は判定しない。","boundary":"沈黙を拒否とも断定しない。支援者が代理入力した場合は本人確認済みと混同しない。"},{"id":"DOT-064","title":"本人の会議参加準備","group":"支援","fields":["同席・別席・代弁の範囲","話したい議題","伝え方","事前資料","休憩と退出の合図","言い残し"],"proposal":"提案：本人が同席・別席・代弁の範囲、話したい議題、伝え方、事前資料、休憩・退出合図を選ぶ会議参加準備票。本人の希望と周囲の懸念を分け、会議後の言い残しも確認する。多数決を本人の意思としない。","boundary":"家族を一律に排除しない。対立の詳細は現行端末に集積せず、別管理の所在と調整状態だけ扱う。"},{"id":"DOT-065","title":"私的な空間の境界","group":"支援","fields":["入室前の知らせ方","返事を待つ方法","触れてよい私物","私的な会話の場所","本人が望む配慮"],"proposal":"提案：入室前の知らせ方、返事を待つ方法、触れてよい私物、私的な会話をする場所を本人と選ぶ境界カード。本人が望む配慮項目だけを記し、鍵番号・機微な会話内容は保存しない。","boundary":"施錠を推奨する機能ではない。避難や安全上の事項は専門職が判断し、端末の秘密保管を保証しない。"},{"id":"DOT-066","title":"説明と残った質問","group":"支援","fields":["説明テーマ","本人が示した理解","残った質問","別の示し方","再説明の希望"],"proposal":"提案：説明テーマごとに本人が示した理解、残った質問、別の示し方、再説明の希望を残す対話票。読み上げ・絵・実物等で確かめ、正誤点数や能力判定には使わない。","boundary":"理解できない人という評価に転用しない。専門判断が必要な同意能力判定は行わない。"},{"id":"DOT-067","title":"利用者会の提案と回答","group":"支援","fields":["議題募集","代表の選び方","任期と交代希望","本人側の提案","運営側の回答","持帰る説明"],"proposal":"提案：利用者会の議題募集、代表の選び方・任期・交代希望、本人側の提案、運営側の回答、持ち帰る説明を一続きにする代表活動票。職員による一方的な代表指名を前提にしない。","boundary":"代表が全員の意見を代弁したと断定しない。少数意見や代表を望まない選択も残す。"},{"id":"DOT-068","title":"改善約束と本人確認","group":"支援","fields":["本人が望む解決","約束した改善","確認日","本人への報告","未解決理由","正式記録の所在"],"proposal":"提案：仮IDで『本人が望む解決・約束した改善・確認日・本人への報告・未解決理由』を結ぶ改善確認票。詳細は別管理の所在だけ記し、担当者の完了と本人の確認を区別する。","boundary":"秘密の苦情台帳にはできない。詳細や実名は別管理とし、管理者だけの『満足』推定で終結させない。"},{"id":"DOT-069","title":"今日の伝え方メニュー","group":"支援","fields":["本人が選ぶ伝え方","場面","相手の役割","候補","見直しの希望"],"proposal":"提案：本人が『今日は文字・絵・身振り・音声など』から選ぶ伝え方メニュー。場面や相手に応じた候補を併記し、一つの方式へ固定しない。支援機器を自動選定せず、本人・専門職が見直す。","boundary":"診断や話せる程度から方式を自動決定しない。本人の表現を職員の解釈へ置き換えない。"},{"id":"DOT-070","title":"本人が増やしたい言葉","group":"支援","fields":["言いたかった表現","本人が選んだ表現","絵の所在","使う場面","紙やAACへの追加確認"],"proposal":"提案：本人が『言いたかったが選択肢になかった言葉』を残す語彙追加候補箱。本人が選んだ表現・絵・使う場面を確認し、既存AACや紙へ手動で追加する準備票を作る。発言を自動生成しない。","boundary":"機器を無断変更しない。本人の意図を推測して語彙を代作せず、画像の利用権も確認する。"},{"id":"DOT-071","title":"AACの利用準備","group":"支援","fields":["機器の所在","本人から届く位置","動作確認","充電","持出し担当","使えなかった時間"],"proposal":"提案：本人のAACについて所在、本人から届く位置、動作確認、充電・持ち出し担当を確かめる利用準備票。機器の所有・利用制限を職員の便宜だけで変えず、使用できない時間を人が振り返る。","boundary":"機器のパスコード・アカウントは保存しない。位置や身体への装着は専門職と本人が確認する。"},{"id":"DOT-072","title":"ルールの見直し対話","group":"支援","fields":["ルールの目的","本人が困る点","代替策","調整を判断する役割","試行期間","本人への説明"],"proposal":"提案：ルールの目的、本人が困る点、代替策、個別調整の可否を判断する人、試行期間、本人への説明をまとめる見直し票。禁止の自動解除や法令判定ではなく、施設内で再検討する材料を整える。","boundary":"安全上・法令上の制約を自動で解除しない。本人の希望を『わがまま』等で分類しない。"},{"id":"DOT-073","title":"事故後の対策再確認","group":"支援","fields":["初動記録の所在","要因検討","対策","再確認日","結果","他部署適用の要否"],"proposal":"提案：事故・ヒヤリハットを一件に束ね、初動記録の所在→要因検討→対策→再確認日→結果→他部署適用の要否まで追う。詳細は正式管理先参照にし、未検証は完了扱いしない。","boundary":"事故の自動分類・過失判定・自動通報はしない。職員別権限がないため詳細事故記録は保存しない。"},{"id":"DOT-074","title":"服薬介助の指示確認控え","group":"支援","fields":["依頼の所在","専門職確認","現行指示書の管理先","版と変更確認日","不一致","照会待ち"],"proposal":"提案：服薬介助の確認票に依頼・専門職確認・現行指示書の管理先と版・変更確認日を結ぶ。不一致・飲めなかった場合は照会待ちを残し、専門職からの回答を人が確認する。","boundary":"投薬判断・量の計算・飲み直し指示はしない。薬名等は正規台帳参照のみ。医療職による仕様レビュー必須。"},{"id":"DOT-075","title":"感染事案の連絡確認控え","group":"支援","fields":["正式記録の所在","時間帯と場所の確認状態","専門機関への照会","回答の変更","周知確認"],"proposal":"提案：感染事案の運用板で、正式記録の所在、関連する時間帯・場所の確認状態、専門機関への照会、返答・変更の有無、周知確認を一件にまとめる。症状や接触者名簿は正規管理先で扱う。","boundary":"感染診断・接触者認定・隔離日数・出勤可否を自動判定しない。機微本文は保存しない。"},{"id":"DOT-076","title":"代替策と解除条件の確認","group":"支援","fields":["代替策の記録所在","組織と専門職の判断","具体的な解除条件","次の確認予定","解除の実確認"],"proposal":"提案：廃止へ向けたレビュー票に代替策を試した記録の所在、専門職・組織の判断、具体的解除条件、次の確認予定、実際の解除確認を結ぶ。承認の自動継承をしない。","boundary":"拘束の許可・方法を提案しない。チェック済みを適法認定にしない。実名等は保存せず専門職レビュー必須。"},{"id":"DOT-077","title":"技能の実技確認","group":"学び","fields":["技能","見学","同伴実施","指導者の実技確認","条件付き単独","再確認条件"],"proposal":"提案：技能ごとの確認票に見学→同伴実施→指導者の実技確認→条件付き単独の段階と再確認条件を残す。担当役が正式な確認記録を照合し、受講済みだけで独り立ち扱いにしない。","boundary":"資格・法定配置・能力を自動判定しない。人事評価や順位化へ転用しない。職員情報は最小化。"},{"id":"DOT-078","title":"退出と帰着の手動確認","group":"支援","fields":["合意した開始と終了見込み","連絡担当役","連絡がない場合の手順","退出確認","帰着確認"],"proposal":"提案：事前に合意した開始・終了見込み、連絡を受ける担当役、連絡がない場合の確認手順を一枚にする。手動の退出・帰着確認を残し、画面を見ていない間の自動監視はうたわない。","boundary":"位置追跡・音声監視・自動救援はしない。ローカル画面を安全装置の代わりにしない。"},{"id":"DOT-079","title":"依頼と利益相反の確認","group":"支援","fields":["依頼内容の種別","施設の方針","相談先","保留理由","本人への説明","引継ぎ相談"],"proposal":"提案：依頼内容を個人情報なしの種別で整理し、施設の方針・相談先・返答保留理由・本人へ説明する要点を確認する。受け取る／断るを自動決定せず、利益相反がある場合の引継ぎ相談も残す。","boundary":"利用者を問題人物と分類しない。依頼の秘密や贈答者名を保存せず法人規程を人が確認する。"},{"id":"DOT-080","title":"一日参加の受入票","group":"支援","fields":["許可された業務","行わない介助","手順の所在","監督する役","本人への案内","説明の確認","終了時の振り返り"],"proposal":"提案：当日の活動に合わせた短い受入票。許可された業務、行わない介助、現行手順の所在、監督する役、本人への案内、説明し返した確認、終了時の振り返りを結ぶ。アカウント権限は付与しない。","boundary":"実際の個人情報を簡易票へ複写しない。職員別権限があるように表示しない。"},{"id":"DOT-081","title":"当番の連絡準備","group":"支援","fields":["当番役","到達確認日","不通時の次の役割","専門判断の範囲","連絡を試した結果"],"proposal":"提案：勤務開始時に当番役、到達確認日、不通時の次の連絡先、専門判断が必要な範囲を確認する当番準備票。連絡を試した結果は手動記録し、番号掲載だけで準備済みにしない。","boundary":"緊急性の自動判定や救急要請はしない。ツールへの入力を現場の緊急対応より先に求めない。"},{"id":"DOT-082","title":"合意した作業範囲の確認","group":"支援","fields":["希望する相談経路","合意した範囲","避ける条件","補助役","正式記録の所在","見直し時期","本人への説明確認"],"proposal":"提案：相談本文や健康情報を保存せず、本人が希望する相談経路、合意済みの作業範囲・避ける条件・補助役、正式記録の所在、見直し時期、本人への説明確認をまとめる。就業再開や再担当は自動判定しない。","boundary":"当事者の訴えを自動採点しない。被害内容・健康情報・相手実名を共有端末に置かない。"},{"id":"DOT-083","title":"休憩を引き継ぐ","group":"休息","fields":["休憩枠","代行担当役","引受ける範囲","開始確認","復帰確認","中断して残った休憩"],"proposal":"提案：休憩枠に代行の担当役、引き受ける範囲、開始・復帰の手動確認を結ぶ。中断した休憩は未消化として残し、引受不成立を責任者へ相談するためのメモにする。","boundary":"休憩未取得を自動で職員責任にしない。法定休憩や労務適法性を判定しない。"},{"id":"DOT-084","title":"訂正の影響と再提出","group":"データ","fields":["原記録の所在","変更種別と理由","旧版との関係","影響する出力","訂正連絡","取下げと再提出確認"],"proposal":"提案：訂正影響表。原記録の管理先、変更種別・理由、旧版との関係、影響する出力・実績票・他機関の参照先、訂正連絡・取下げ・再提出の確認を結ぶ。正式記録や請求をここで上書き・提出しない。","boundary":"本ツールを正規記録保管庫や改ざん防止監査システムと称しない。機微原文を保存せず参照番号に限定。"},{"id":"DOT-085","title":"希望と提供条件の照合","group":"支援","fields":["本人が求める支援","確認した提供条件","未確認事項","再相談できる条件","人の判断"],"proposal":"提案：紹介先ごとに本人が求める支援、事業所が確認した提供条件、未確認事項、再相談できる条件を対照する受付照合票。可否判定は担当者が行い、診断名から自動拒否しない。","boundary":"実名・診断名不要。適格性、受入れ可否、優先順位を自動判定しない。 単独担当者の端末内モック限定。"},{"id":"DOT-086","title":"追加受入れ日の条件","group":"支援","fields":["専用スペース","準備の所要","必要な対応役","既存利用への影響","代替案","未確認の条件"],"proposal":"提案：追加受入れ日の条件票に専用スペース、準備の所要、必要な対応役、既存利用者への影響、代替案を手入力。人数の空きとは別に条件確認待ちを表示する。","boundary":"法定配置計算、利用可否の自動判定はしない。 単独担当者の端末内モック限定。"},{"id":"DOT-087","title":"待機希望の継続確認","group":"支援","fields":["最終確認日","希望継続・保留・連絡未成立","次回確認","施設の順序ルール","例外理由"],"proposal":"提案：待機登録に最終確認日、希望継続／保留／連絡未成立、次回確認、施設が定めた順序ルールと人による例外理由を記録。返信がない人を自動削除・後順位化しない。","boundary":"障害等を使った自動優先順位は禁止。未返信を辞退とみなさない。 単独担当者の端末内モック限定。"},{"id":"DOT-088","title":"未接続条件の匿名整理","group":"支援","fields":["条件の区分","確認できた件数","未確認理由","重複相談の確認","少数区分を伏せる基準"],"proposal":"提案：未接続相談を「時間帯／設備／支援体制／サービス説明不足」等の条件だけで集計し、少数件を伏せた地域課題メモを作る。件数と未確認理由を分け、人が共有可否を決める。","boundary":"個人の事情・病名を集計しない。小数件からの再識別や公開は別途確認。 単独担当者の端末内モック限定。"},{"id":"DOT-089","title":"最後の支援から次の初日へ","group":"支援","fields":["最後の支援","本人が選ぶ引継ぎ項目","受入先の受領と引受","初回準備","未定時の代替相談先","終了後の再相談先"],"proposal":"提案：支援切替の接続票。最後の支援、本人が選んだ引継ぎ項目、受入先の受領・引受、初回準備、未確定の代替相談先を依存関係で並べる。日程変更時に影響する初回支援だけ再確認し、終了後の再相談先も残す。","boundary":"児童の実名・詳細記録を入れない。本人の希望と共有範囲を別途確認。 単独担当者の端末内モック限定。"},{"id":"DOT-090","title":"支援区間と引受の境界","group":"支援","fields":["本人が望む支援区間","引受済みの行為と時間","担当未定の区間","重複","対象外範囲","代替相談先"],"proposal":"提案：本人が支援を望む区間と、各機関が引き受けた行為・時間帯を重ねる連携境界表。担当未定の空白と役割の重複を示し、対象外の範囲・代替相談先・回答日を残す。支援者やサービスを自動割当てしない。","boundary":"本人が一人で過ごす希望を空白問題と自動判定しない。 単独担当者の端末内モック限定。"},{"id":"DOT-091","title":"契約説明の版差分","group":"仕事","fields":["旧版の所在","現行版の所在","料金の変更","提供時間の変更","休止終了条件","本人へ渡した版","未説明点"],"proposal":"提案：契約条件の旧版と現行版の差を、料金・提供時間・休止終了条件ごとに示す説明差分票。本人へ渡した版、説明済み変更点、未説明点を残す。契約締結や同意の代理は行わない。","boundary":"電子署名・契約の自動承認はしない。法務と制度担当の確認が必要。 単独担当者の端末内モック限定。"},{"id":"DOT-092","title":"料金の根拠と説明","group":"支援","fields":["対象品と便宜","給付内・別負担の確認先","金額根拠","改定日","本人向け説明","未確認項目"],"proposal":"提案：費目ごとに対象の品・便宜、給付内／別負担の確認先、金額根拠、改定日、本人向け説明文をまとめる料金根拠カタログ。未確認項目を残し、徴収可否は自動判定しない。","boundary":"会計・法務確認前の費用案を確定額にしない。実徴収は行わない。 単独担当者の端末内モック限定。"},{"id":"DOT-093","title":"概算受領と実費の精算案","group":"支援","fields":["対象期間","概算受領","実費根拠","配分方法","残額","返還または同目的充当の確認"],"proposal":"提案：費目・対象期間ごとに概算受領、実費根拠、手動確認した配分方法、残額、返還／同目的への充当の確認を並べる精算案。別費目への転用は未解決として表示する。","boundary":"返金送金、適法性保証、自動振替はしない。端数・欠食の扱いは専門確認。 単独担当者の端末内モック限定。"},{"id":"DOT-094","title":"領収証の交付と再発行","group":"支援","fields":["受領の内部番号","領収証番号","対象月","交付先区分","渡した日","再発行理由"],"proposal":"提案：受領確認の内部番号に、領収証番号・対象月・交付先区分・渡した日・再発行理由を紐付ける照合票。再発行は元受領と結び、二重受領として集計しない。","boundary":"口座番号・実名は保存しない。正式領収証発行や会計証明の保証はしない。 単独担当者の端末内モック限定。"},{"id":"DOT-095","title":"預り物の二者確認控え","group":"支援","fields":["預り番号","保管担当役","出納確認役","現物残","帳簿残","確認日","正式な証跡の所在"],"proposal":"提案：預り物は番号だけで、保管担当役、出納確認役、現物残と帳簿残の確認日、差異と未点検を管理する点検控え。別の人が確認した証跡の所在を残し、ソフトが二者承認を保証しない。","boundary":"認証・権限分離は既存にない。口座情報・暗証番号は入れず、実際の二者確認は別手段。 単独担当者の端末内モック限定。"},{"id":"DOT-096","title":"買物代行の精算封筒","group":"支援","fields":["依頼品","預かった概算","購入明細の所在","品物の引渡し","釣銭の引渡し","確認待ち差額"],"proposal":"提案：代行1回ごとに依頼品、預かった概算、購入明細の所在、品物と釣銭の引渡し、確認待ち差額をまとめる精算封筒票。本人の希望外の購入を完了扱いしない。","boundary":"購入や返金を実行しない。レシート画像・個人の購入事情は最小化する。 単独担当者の端末内モック限定。"},{"id":"DOT-097","title":"来訪から退出まで","group":"支援","fields":["目的区分","同伴と対応職員役","案内可能区域","受付確認","退出確認","来訪者証返却"],"proposal":"提案：来訪の目的区分、確認済み同伴・対応職員役、案内可能区域、受付と退出、来訪者証の返却を一枚で確認する受付票。予定登録だけで入館許可にしない。","boundary":"顔認識・危険人物判定・入退室制御はしない。利用者の外出自由を制限しない。 単独担当者の端末内モック限定。"},{"id":"DOT-098","title":"照会の根拠目次","group":"データ","fields":["照会項目","対象日","原記録の所在と版","確認日","数値差","説明を要する空欄"],"proposal":"提案：照会項目から、対象日、参照する原記録の所在・版・確認日、数値差、説明を要する空欄をたどる根拠目次を作る。根拠未確認と人が確認済みを区別し、原記録は改変しない。","boundary":"監査合格・法令適合・改ざん防止を保証しない。健康情報の大量複製を避ける。 単独担当者の端末内モック限定。"},{"id":"DOT-099","title":"提供内容の本人確認控え","group":"支援","fields":["その日の提供内容","時間","本人の確認状態","質問","元記録との訂正関係"],"proposal":"提案：その日の提供内容と時間を本人が確認する小さな控えを用意し、「確認済み／質問あり／後日確認」を分ける。内容訂正は元記録との関係を残し、出席しただけで確認済みにしない。","boundary":"署名代行・同意推定はしない。本人が質問したことを不利益に扱わない。 単独担当者の端末内モック限定。"},{"id":"DOT-100","title":"確定受領額の説明控え","group":"支援","fields":["正式請求の参照番号","サービス月","事業所受領分","本人負担分","確定か未確定か","説明確認"],"proposal":"提案：正式請求システムで確定した受領額の参照番号を用い、サービス月・事業所受領分・本人負担分を区別する説明控えを作る。自己負担ゼロを通知不要と扱わず、未確定額は明示する。","boundary":"給付額を計算・請求しない。転記は正式結果との人手照合が必要。 単独担当者の端末内モック限定。"},{"id":"DOT-101","title":"参加条件の照合","group":"生活","fields":["本人の希望","環境","説明方法","同伴と退出条件","公式記載","回答確認済み","未確認"],"proposal":"提案：本人の希望と参加先の環境・説明方法・同伴・退出条件を、公式記載／回答確認済み／未確認に分ける参加条件票。会場、ピア会、補助犬同伴、受診の確認項目を切替え、予約や利用可否の自動判断はしない。","boundary":"本人の中断・不参加を尊重。診断名、他参加者の話、証明書画像を保存しない。医療や補助犬受入れは専門職等の確認が前提。自動予約・拒否判断はしない。"},{"id":"DOT-102","title":"読みたい本の利用形式","group":"学び","fields":["作品の仮ID","必要な形式","見出し移動","図表説明","確認した版と所在","使う機器","未確認機能"],"proposal":"提案：「読みたい本」単位に必要な形式・見出し移動・図表説明等と、図書館で確認した版・所在・使う機器を照合。見つからない形式を相談用に整理し、本文の複製や利用資格判定はしない。","boundary":"著作物を取り込まない。認証情報や障害証明を保存しない。 実運用の前に、運用者が安全性を確認してください。単独担当者の端末内で仮ID・最小情報のみ。"},{"id":"DOT-103","title":"発表先の選択比較","group":"創作","fields":["見てほしい相手","展示形式","費用の前提","原作の預け方","返却条件","必要な手助け","見送る理由"],"proposal":"提案：公募展・共同展示・個展等について、見てほしい相手、展示形式、費用、原作の預け方・返却条件、必要な手助けを比較する発表先選択票。選ばない案も残し、応募や権利許諾は別途本人判断。","boundary":"著作権・契約の自動解釈、作品公開、応募送信はしない。専門家確認が必要な条件は保留。 実運用の前に、運用者が安全性を確認してください。単独担当者の端末内で仮ID・最小情報のみ。"},{"id":"DOT-104","title":"通勤の判断点カード","group":"生活","fields":["経路の目印","乗換えの判断点","迷った時に止まる場所","尋ね方","練習で迷った点","運休時の相談方針"],"proposal":"提案：通勤ルートの目印、乗換えの判断点、間違えた時に止まる場所・尋ね方を紙カード化。同行練習で迷った箇所だけ更新し、通常経路と運休時の相談方針を分ける。位置追跡はしない。","boundary":"安全な単独移動を認定しない。支援者による現地確認が前提。自宅住所・行動履歴は保存しない。 実運用の前に、運用者が安全性を確認してください。単独担当者の端末内で仮ID・最小情報のみ。"},{"id":"DOT-105","title":"情報入口の点検","group":"連絡","fields":["連絡経路","本人が直接使える方法","依頼済みか未確保か","確認する場所","届かなかった場面","家族が引受けない範囲"],"proposal":"提案：連絡経路ごとに本人が直接使える文字・音声・専門通訳等、依頼済み／未確保、確認する場所、届かなかった場面を整理する情報入口点検。家族が引き受けない範囲も明示し、実内容や子どもの情報は保存しない。","boundary":"会社の機密内容や社内ログを取り込まず、情報の種類と困った場面だけ残す。 実運用の前に、運用者が安全性を確認してください。単独担当者の端末内で仮ID・最小情報のみ。"},{"id":"DOT-106","title":"次の役割への学習機会","group":"学び","fields":["本人が望む役割","企業に確認した必要技能","示せる経験","学習機会","受講の配慮","相談論点"],"proposal":"提案：本人が望む次の役割について、企業に確認した必要技能、既に示せる経験、学習機会、受講に必要な配慮、次に相談する論点を対応付ける成長機会票。人事評価・昇進可能性を採点しない。","boundary":"職業適性・昇進・雇用可否の自動判定をしない。外部提出用履歴書は自動生成しない。 実運用の前に、運用者が安全性を確認してください。単独担当者の端末内で仮ID・最小情報のみ。"},{"id":"DOT-107","title":"共同生活の調整比較","group":"生活","fields":["各人の希望","重なる場面","試せる代案","試行期間","再確認結果"],"proposal":"提案：生活音・共有スペース等の一案件について、各人が望む過ごし方、重なる場面、試せる代案、試行期間、再確認結果を仮IDで並べる生活調整票。多数決や自動の責任判定はしない。","boundary":"深刻な暴力・権利侵害を話し合いで処理させない。別の適切な専門対応が必要。 実運用の前に、運用者が安全性を確認してください。単独担当者の端末内で仮ID・最小情報のみ。"},{"id":"DOT-108","title":"自分の休息ノート","group":"休息","fields":["休息で取り戻したいこと","実際にできたこと","休めなかった条件","次回変えたいこと"],"proposal":"提案：家族本人が休息で取り戻したいこと、実際にできたこと、休めなかった理由、次回変えたい点を短く振り返る休息ノート。ケアの代替担当表とは分け、罪悪感や疲労を点数評価しない。","boundary":"家族の記録を利用者の記録へ混ぜない。未成年者の詳細や医療情報を保存しない。 実運用の前に、運用者が安全性を確認してください。単独担当者の端末内で仮ID・最小情報のみ。"},{"id":"DOT-109","title":"きょうだい自身の希望","group":"生活","fields":["自分が守りたい生活","手伝えること","今は引受けられないこと","まだ話せないこと","家族の期待"],"proposal":"提案：成人きょうだい自身が守りたい生活、手伝えること、今は引き受けられないこと、まだ話せないことを自分用に整理する希望票。家族の期待を本人の同意と別表示し、自動で支援担当へ割り当てない。","boundary":"成人のみを想定。家族関係を裁定せず、きょうだいの私的希望を他の家族へ自動共有しない。 実運用の前に、運用者が安全性を確認してください。単独担当者の端末内で仮ID・最小情報のみ。"},{"id":"DOT-110","title":"架空のお金で支払練習","group":"学び","fields":["架空の店","架空の予算","支払方法","購入金額","残額","足りない時に尋ねること"],"proposal":"提案：架空の店と金額で、現金・前払い残高等の支払選択、残りの金額、画面の確認、足りない時に止めて尋ねる流れを試す支払練習。実残高・実カード・決済サービスとは接続しない。","boundary":"借入・後払い利用を勧めない。口座、カード番号、認証情報を一切入力させない。 実運用の前に、運用者が安全性を確認してください。単独担当者の端末内で仮ID・最小情報のみ。"},{"id":"DOT-111","title":"避難の机上リハーサル","group":"生活","fields":["公式に確認した避難先","手段","協力者の承諾状態","訓練で詰まった点","再調整先"],"proposal":"提案：本人の個別避難リハーサル票。自治体等が確認した避難先・手段、協力者の承諾／未定、本人参加の訓練で詰まった地点、再調整先を一続きに整理。警報判断や最適経路を自動決定せず、架空地図で検討する。","boundary":"生命安全に関わる。自動避難勧告・経路保証はしない。住所や実名を保存せず、正式計画は別管理。防災・福祉専門職の承認が前提。"},{"id":"DOT-112","title":"用具の来歴と専門確認","group":"生活","fields":["用具の仮ID","製作や処方資料の所在","本人が感じた変化","専門職への照会","調整後の確認日"],"proposal":"提案：本人の補装具の来歴・専門確認カード。仮の用具IDに製作／処方資料の所在、本人が感じた変化、専門職への照会、調整後の確認日を関連付ける。修理方法や適合性・再支給の可否は判定しない。","boundary":"身体情報は機微情報。実測値・処方内容は正式記録側に保持しこのツールには所在のみ。適合、修理、使用継続は専門職が判断。自己改造の誘導はしない。"},{"id":"DOT-113","title":"別れの情報と参加希望","group":"生活","fields":["情報を知りたい方法","確かめたいこと","参加または不参加","思い出を残す方法","変更した希望"],"proposal":"提案：別れの情報・参加希望メモ。誰からどの方法で知りたいか、確かめたいこと、追悼への参加／不参加、思い出を残す方法を本人の希望として整理し、変更を受け止める。通知の自動送信はしない。","boundary":"悲嘆を診断・採点せず、参加や気持ちの表出を強制しない。遺族や第三者の実名・死因・体験詳細を保存しない。専門職・当事者による設計確認が必要。"},{"id":"DOT-114","title":"つまずきの経路図","group":"学び","fields":["今の単元","前提概念","小問で確認した根拠","未確認","最小の復習順"],"proposal":"提案：単元を前提概念でつなぐ「つまずき経路図」。講師が小問で確かめた根拠と未確認を置き、今の単元へ戻るための最小の復習順を手動で組む。人の能力を固定分類しない。","boundary":"観察不足を能力不足としない。匿名教材例を基本とし未成年情報は保存しない。"},{"id":"DOT-115","title":"誤答の分かれ道","group":"学び","fields":["架空の誤答","考え方の仮説","対比問題","説明し直す観点","再確認問題"],"proposal":"提案：「誤答の分かれ道」教材帳。匿名の架空誤答に、考え方の仮説、確かめる対比問題、説明し直す観点、再確認問題を結ぶ。分類は講師が保留・修正できる。","boundary":"AIによる誤概念認定や学習者ラベル化をしない。誤答は講師作成の例のみ。"},{"id":"DOT-116","title":"学習の到達と継続判断","group":"学び","fields":["目標","確認課題","今回の証拠","終了・復習・別説明・再確認","次回開始課題"],"proposal":"提案：目標・確認課題・今回の証拠を結ぶ「学習到達と継続判断票」。講師が終了／復習／別の説明／再確認を選び、次回の開始課題へつなぐ。回数消化だけで達成とせず、未確認を残す。","boundary":"未実施を未達成へ変換しない。未成年の回答原文を保存しない。"},{"id":"DOT-117","title":"間隔を空けた想起","group":"学び","fields":["教材ID","初回日","復習実施日","講師が選ぶ次の間隔","答えを見ずに試す問題"],"proposal":"提案：「間隔を空けた想起」キュー。教材IDに初回・復習実施日、講師が選ぶ次の間隔、答えを見ずに試す問題を結ぶ。遅れを罰点にせず、開いた時に復習候補を示す。","boundary":"最適間隔を断定せず自動能力推定もしない。常時通知を約束しない。"},{"id":"DOT-118","title":"解答例から自力問題へ","group":"学び","fields":["講師作成の完成例","一部空欄版","自力問題","残す思考段階","例と練習の順番"],"proposal":"提案：講師が書いた解答例を、完成例→一部空欄→自力問題へ展開する教材ペア編集。どの思考段階を残すか選び、同じ概念の例と練習を交互に並べる。自動出題・自動採点はしない。","boundary":"空欄にした段階で解けなくなる問題を講師が確認。教材本文は自作だけ。"},{"id":"DOT-119","title":"具体・図・式の対応","group":"学び","fields":["概念","具体場面","図の所在","表の所在","式","対応点の番号","別場面の問い"],"proposal":"提案：一概念の具体場面・図・表・式を対応点で結ぶ「表現変換カード」。講師が同じ要素に番号を付け、どの対応を説明し、別場面へ移す問いを出すか選ぶ。","boundary":"表現の対応誤りは講師が検証。図表は自作し画像大量保存を避ける。"},{"id":"DOT-120","title":"予想と再生の差","group":"学び","fields":["答えを隠した問い","本人の予想","講師が確認した結果","ずれた内容","次に復習する対象"],"proposal":"提案：「予想と再生の差」振り返り。答えを隠した問いに本人が答えられそうか予想し、後で講師が確認した結果と並べる。ずれた内容から本人が次の復習対象を選ぶ。","boundary":"心理・能力評価に転用しない。本人の予想入力は任意、順位付けなし。"},{"id":"DOT-121","title":"分岐レッスン","group":"学び","fields":["題材","共通課題","補充の手掛かり","発展課題","使った分岐","次回直す箇所"],"proposal":"提案：一つの題材に共通課題・補充の手掛かり・発展課題を束ねる「分岐レッスン」。元教材の重複を避け、使った分岐と次回直す箇所を講師が残す。人を固定レベルへ分類しない。","boundary":"能力の固定ラベル化・自動振分けなし。印刷は教材のみで受講者名を載せない。"},{"id":"DOT-122","title":"匿名の練習機会マップ","group":"学び","fields":["授業回","匿名席番号","考える機会","ペアで試す機会","全体で話す希望","次の活動配置"],"proposal":"提案：授業一回だけの匿名席番号に、考える・ペアで試す・全体で話す機会を手動で印す練習機会マップ。希望しない全体発言を強制せず、次の活動配置を調整する。","boundary":"性格評価・参加点・発話監視なし。録音せず一時席番号は授業後に残さない設計。"},{"id":"DOT-123","title":"流暢さと正確さの活動","group":"学び","fields":["活動目的","準備","試行","活動後の訂正","講師作成の誤例","今回絞る訂正項目"],"proposal":"提案：「話す練習と訂正」の授業カード。活動目的を流暢さ／正確さで明示し、準備・試行・活動後の訂正を並べる。講師が作った匿名の誤例を後で扱う箱へ置き、訂正項目を絞る。","boundary":"実際の私的会話や声を保存しない。例は講師が匿名で再構成し自動評価なし。"},{"id":"DOT-124","title":"大人向け教材の適合索引","group":"学び","fields":["題材","実生活での用途","必要語彙","幼すぎる表現","古い設定","修正箇所"],"proposal":"提案：教材の「大人向け適合」索引。題材、実生活での用途、必要語彙、幼すぎる表現や古い設定、講師が直した箇所を保存し、同じ言語目標に合う題材を再利用する。","boundary":"教材本文は複製せず出典URLと自分の修正メモのみ。年代・文化の一律判断なし。"},{"id":"DOT-125","title":"持帰り練習の小単位","group":"学び","fields":["目標","つまずく箇所","短時間の案","長めの案","楽器と場所の条件","自力開始できた範囲"],"proposal":"提案：楽曲の反復構造・つまずく箇所から、家で最初に試せる小単位を切り出す持帰り練習メニュー。同じ目標の3分・10分等の案と楽器・場所条件を用意し、レッスン内で自力開始できた範囲を確認する。","boundary":"練習不足を叱責・順位化しない。生活履歴や位置情報は取得しない。"},{"id":"DOT-126","title":"目標と練習と確認","group":"学び","fields":["目標","教材ID","説明","練習","確認課題","不足する工程"],"proposal":"提案：目標×説明・練習・確認の対応表。教材IDと各目標を結び、「説明のみ」「練習あり」「確認課題なし」を示す。音楽なら読譜・リズム等も講師が設定し、偏りを見て授業案を組む。","boundary":"チェックがあるだけで習得済みにしない。少数の目標・教材IDで容量増を抑える。"},{"id":"DOT-127","title":"ルーブリックの境界例","group":"学び","fields":["評価観点","具体的な記述","講師作成の境界例","採点前の確認","今回は見ない観点"],"proposal":"提案：課題ごとの評価観点・具体的な記述・講師作成の境界例を対にするルーブリック編集。採点前に見本で観点を確かめ、今回は見ない観点も明示する。採点は人が行う。","boundary":"自動採点・合否・人物能力の判定なし。実受講者作品でなく講師作成例だけ保存。"},{"id":"DOT-128","title":"設問の不具合台帳","group":"学び","fields":["問題ID","別解","読み違い","選択肢の重なり","文化的前提","再使用前の修正"],"proposal":"提案：「設問の不具合」台帳。問題IDに別解・読み違い・選択肢の重なり・文化的前提の疑いを残し、再使用前の修正待ちへ置く。低正答率と問題不良を自動で同一視しない。","boundary":"自動で成績訂正や学力不足判定をしない。回答原文ではなく架空の解釈例を保存。"},{"id":"DOT-129","title":"テストの時間と配点","group":"学び","fields":["設問ID","講師試解時間","想定時間幅","配点","部分点","必要な解答形式"],"proposal":"提案：設問ごとの講師試解時間・想定時間幅・配点・部分点・必要な解答形式を並べるテスト構成票。合計負荷と配点の偏りを表示し、時間制約が目標に必要かを確認する。","boundary":"標準時間を全員へ固定せず幅で扱う。合理的配慮や公式試験要件を自動判断しない。"},{"id":"DOT-130","title":"試験後の学び方","group":"学び","fields":["練習方法","見直した範囲","誤りの種類","次回変える一つ","次の試験準備"],"proposal":"提案：試験返却時の「学び方の振り返り」。練習方法、見直した範囲、誤りの種類、次回変える一つを本人と整理し、次の試験準備時にその一つを再提示する。","boundary":"失敗の責任追及や性格評価にしない。実成績や未成年の詳細情報は保存しない。"},{"id":"DOT-131","title":"添削から再試行へ","group":"学び","fields":["対象箇所","考える問い","書き直す課題","再確認","返した数","再試行できた数"],"proposal":"提案：指摘を「対象箇所・考える問い・書き直す課題・再確認」にする添削ループ。今回は扱う観点を絞り、講師は返した数と再試行できた数を区別する。本文は保存せず教材内位置だけ扱う。","boundary":"添削結果を自動評価しない。受講者の原稿・個人事情をローカルへ集めない。"},{"id":"DOT-132","title":"添削から再授業へ","group":"学び","fields":["授業回","架空の共通誤り","良い例","まとめて説明する点","個別に返す点","再説明教材"],"proposal":"提案：匿名の共通誤りと良い例を授業回ごとに集計し、まとめて再説明する候補と個別に返す点を分ける「添削から再授業」ボード。再説明する短い教材へ手動でまとめる。","boundary":"少人数の誤例で本人が特定されないよう架空化。個別支援が必要な点を一括処理しない。"},{"id":"DOT-133","title":"一回一観点の相互レビュー","group":"学び","fields":["練習作品の所在","見る観点","根拠","質問","提案","作者が採る点","保留点"],"proposal":"提案：一回一観点の相互レビュー台本。匿名の練習作品、見る根拠、質問と提案の区別、作者が採る／保留する点、次の修正を紙カードにする。講師が進行し共同編集はしない。","boundary":"人格批評・公開順位付け・採点委任を避ける。作品は自作架空例、共有送信なし。"},{"id":"DOT-134","title":"研修で扱う範囲","group":"学び","fields":["確認した困り事","知識技能","手順","道具","実行機会","未確認原因","研修外の確認"],"proposal":"提案：受講者や依頼者へ確認した業務上の困り事を、知識技能・手順・道具・実行機会等に分ける「研修で扱う範囲」票。未確認原因を残し、教える課題と研修外の確認事項を分離する。","boundary":"従業員評価・採用・職務適性判定へ使わない。企業の秘密や個人データは記載しない。"},{"id":"DOT-135","title":"学びを使う一場面","group":"学び","fields":["本人が選ぶ使用場面","試せる機会","必要資源","確認した実施例","できなかった条件"],"proposal":"提案：「学んだことを使う一場面」票。本人が選ぶ使用場面、試せる機会、必要資源、後日確認した実施例・できなかった条件を対応付ける。満足度や出席と別にまとめ、連絡は自動送信しない。","boundary":"企業秘密・健康・実在者の評価を残さず、業務場面を一般化。上司への自動報告なし。"},{"id":"DOT-136","title":"講座の前後確認設計","group":"学び","fields":["講座版","事前課題","事後課題","実施条件","欠測","自己申告か実演か"],"proposal":"提案：講座版ごとの前後確認設計。等しい観点の事前・事後課題、実施条件、欠測、自己申告か実演かを並べる。匿名集計で変化を見るが、少人数の結果から因果効果や優劣を断定しない。","boundary":"教育・雇用の適格性判断なし。名簿や個票を取り込まず架空・匿名集計のみ。"},{"id":"DOT-137","title":"課題で使ってよい助け","group":"学び","fields":["対象工程","AIの扱い","他者の扱い","資料の扱い","本人が説明する部分","代替手段"],"proposal":"提案：課題ごとの「使ってよい助け」設計票。調査・構想・推敲等の工程ごとにAI・他者・資料の扱い、本人が説明する部分、代替手段を明示して課題文へ差込む。利用検出はしない。","boundary":"不正・著者・能力を自動判定しない。AIサービスへ提出物を送らず正式資格要件は別確認。"},{"id":"DOT-138","title":"考えた過程の目次","group":"学び","fields":["構想の所在","試行の所在","迷った選択","修正理由","口頭説明の問い","成果物の所在"],"proposal":"提案：「考えた過程」ポートフォリオ目次。構想・試行・迷った選択・修正理由・短い口頭説明の問いを節目に置き、成果物の所在だけを結ぶ。完成品の巧拙とは別に講師が対話する。","boundary":"著者証明・不正認定・自動採点なし。作品本文や映像は保存せず自作例で検討。"},{"id":"DOT-139","title":"二段階の匿名ミニ投票","group":"学び","fields":["概念問題","個別回答の件数","ペアで話す理由","再回答の件数","次の説明"],"proposal":"提案：講師の自作概念問題で個別に考える→ペアで理由を話す→再回答の匿名件数を並べる二段階ミニ投票票。変化を見て説明を続けるか別例にするか選ぶ。受講者端末やサーバーは不要。","boundary":"成績・人物識別に使わず匿名件数のみ。多数派が正解とは表示しない。"},{"id":"DOT-140","title":"納品と受入の確認","group":"仕事","fields":["成果物","受入条件","確認方法","検査予定日","判定者の役割","未合格箇所","納品と受領と受入"],"proposal":"提案：成果物ごとに受入条件・確認方法・検査予定日・判定者・未合格箇所を紐付け、納品、受領、検査、受入を分けて記録する。無応答を自動承認にしない。","boundary":"法的な検収成立や支払期限を自動判定せず、検収未了を支払猶予へ結び付けない。相手の承認は本人が確認する。"},{"id":"DOT-141","title":"着手の前提条件","group":"仕事","fields":["必要な素材と環境","受領状態","使用可能か","権限不足","不足理由","短縮できない期間"],"proposal":"提案：素材・データ・客先環境を後続工程に結ぶ着手条件票。受領／使用可能／権限不足等を分け、本人の利用確認と不足理由を記録する。揃った日から開始できる工程と短縮できない期間を示し、納期相談用の影響票を作る。","boundary":"納期・契約を一方的に更新しない。秘密情報は保存せず、接続・権限変更を代行しない。"},{"id":"DOT-142","title":"受取側の互換性確認","group":"仕事","fields":["利用ソフト","形式","文字コード","添付の要否","試料の開封確認","未確認項目"],"proposal":"提案：受取側の利用ソフト、形式、文字コード、添付の要否と小さな試料の開封確認を記録する。納品前に互換性未確認項目を表示する。","boundary":"受取側ソフトの互換性を保証しない。実データの試送を自動実行しない。"},{"id":"DOT-143","title":"案件終了と権限返却","group":"仕事","fields":["顧客システムの仮ID","アクセス終了依頼","顧客側の担当役","解除確認日","未確認"],"proposal":"提案：顧客システムごとにアクセス終了依頼、顧客側担当者、解除確認日、未確認を記録する。案件終了と権限返却完了を別状態にする。","boundary":"解除を自動実行せず、確認のために無断再ログインもしない。認証情報は保持しない。"},{"id":"DOT-144","title":"ドメインの移管手順控え","group":"仕事","fields":["所有者の役割","管理担当役","移管予定先","各社条件の確認日","変更順","結果"],"proposal":"提案：ドメインの登録者、管理担当、移管予定先、各社条件の確認日、変更順と確認結果を記録する。転出制約が未確認なら手順を保留表示する。","boundary":"現行条件は人が各社に確認。移管申請、認証コード保存、名義変更は行わない。"},{"id":"DOT-145","title":"保証範囲と問合せ条件","group":"仕事","fields":["納品時の対象環境","保証対象と期限","再現条件","顧客側変更の有無","人が決めた対応"],"proposal":"提案：納品時の対象環境・保証対象・期限に、問い合わせの再現条件と顧客側変更の有無を照合する票を作る。対応種別は人が決め、契約外候補は相談待ちにする。","boundary":"瑕疵・契約不適合・免責を自動判定しない。相手の権利を否定する通知を作らない。"},{"id":"DOT-146","title":"返却・消去の確認票","group":"データ","fields":["保管場所の種類","対象区分","契約上の条件","例外の確認先","実施確認日"],"proposal":"提案：保管場所の種類、対象区分、契約上の返却・消去条件、例外の確認先と実施確認日を管理する。実データは抱えず、終了処理の確認票だけ残す。","boundary":"法定保存の要否は専門家等に確認。自動削除せず、完全消去の証明を保証しない。"},{"id":"DOT-147","title":"協力者と事前承認","group":"仕事","fields":["顧客条件","協力者やサービスの区分","データ区分","事前承認","変更通知","必要条項の確認"],"proposal":"提案：顧客条件と協力者・サービス・扱うデータ区分を紐付け、事前承認、変更通知、必要条項の確認結果を記録する。変更時は関係する条件だけ再確認に戻す。","boundary":"サービスの適法性や越境移転を自動判定しない。利用許可も共有も自動実行しない。"},{"id":"DOT-148","title":"守秘と競業条件の整理","group":"仕事","fields":["守秘対象","競業対象","専属範囲","地域","期間","例外","専門家への確認"],"proposal":"提案：守秘対象、競業対象、専属範囲、地域、期間、例外を別欄で整理し、手入力した既存案件との重なり候補を示す。条文と専門家への確認事項を紐付ける。","boundary":"有効性、違法性、契約違反を自動判定しない。既存顧客名の不要な開示をしない。"},{"id":"DOT-149","title":"指示と受入の権限","group":"仕事","fields":["契約当事者の役割","仲介者","実利用者","仕様指示の権限","受入権限","正規窓口での確認"],"proposal":"提案：契約当事者、仲介者、実利用者、仕様指示権限、受入権限を案件に分けて登録する。別経路の指示は権限未確認として残し、正規窓口での確認記録を付ける。","boundary":"権限の有無は契約等を人が確認。相手の法的代理権を保証しない。"},{"id":"DOT-150","title":"発注条件の手動控え","group":"仕事","fields":["条件の控え","原文の参照先","保存確認日","未確定事項","外部アクセス終了前の確認"],"proposal":"提案：発注条件の手動控え、原文の参照先、保存確認日、未確定事項を案件にまとめる。外部アクセス終了前に控えの有無を確認し、原本と転記を明確に区別する。","boundary":"自動取得・スクレイピングはしない。転記の証拠能力や原本同一性を保証しない。"},{"id":"DOT-151","title":"募集と面談説明の差","group":"仕事","fields":["募集の仕事","雇用か委託か","必要作業","テスト条件","面談後の説明","不一致の確認"],"proposal":"提案：募集記載の仕事内容、雇用・業務委託の表現、必要作業、テスト条件と、面談後の説明を対にする。不一致を確認待ちとして残してから受注可否を人が決める。","boundary":"虚偽広告や労働者性を自動認定しない。公開告発や通報を自動化しない。"},{"id":"DOT-152","title":"依頼者の独立確認","group":"仕事","fields":["知った経路","独立した公式窓口","要求された情報の種類","確認結果","保留理由"],"proposal":"提案：依頼者を知った経路、独立して確認した公式窓口、要求された情報の種類、確認の結果と保留理由を記録する。本人確認が済むまで情報提供の判断を保留にできる。","boundary":"詐欺判定・信用スコア・公開ブラックリストを作らない。身分証や金融口座情報を保存しない。"},{"id":"DOT-153","title":"責任条件の相談準備","group":"仕事","fields":["責任が生じる行為","対象損害","上限の記載","除外","通知と協力条件","準拠法の記載","専門家への問い"],"proposal":"提案：責任が生じる行為、対象損害、上限の記載、除外、通知・協力条件、準拠法の記載を手動で分ける。不明欄を残し、条文付きの専門家相談票を作る。","boundary":"条項の適法性や受諾可否、賠償額を判定しない。保険の推奨・見積もりもしない。"},{"id":"DOT-154","title":"型と参照を保つ移行準備","group":"データ","fields":["参照ID","項目型","配列境界","識別子の原値","孤立参照","曖昧な分割","未解決"],"proposal":"提案：台帳の参照ID・項目型・配列境界・識別子原値を保つ移行パック。JSONと型辞書、CSV用の子表等を用意し、孤立参照・分割曖昧・自動変換の疑いを取込前に表示する。人が解決するまで原値を保つ。","boundary":"外部サービスへ自動取込しない。曖昧な配列や失われた桁は推測復元せず、公的個人番号を扱わない。"},{"id":"DOT-155","title":"CSVの数式解釈点検","group":"データ","fields":["原値の所在","先頭文字の候補","文字列化した確認値","原値を保つJSON","出力先の確認"],"proposal":"提案：CSV出力前に数式として解釈されうる先頭文字等の候補を表示し、文字列化した確認用出力と原値を保つJSONを選べるようにする。元データは書き換えない。","boundary":"完全防御を保証しない。危険な実式を試さず、原値を勝手に消さない。"},{"id":"DOT-156","title":"読取用パッケージの目次","group":"データ","fields":["標準形式の所在","項目説明","単位","状態値の意味","添付参照","不足一覧"],"proposal":"提案：標準形式のデータに項目説明、単位、状態値の意味、添付参照と不足一覧を付けた読取用パッケージを作る。実行コードを含めず、人が読める索引を用意する。","boundary":"添付本体の自動収集はしない。個人情報を不要に含めない。永続可読性を保証しない。"},{"id":"DOT-157","title":"取得範囲と期待件数","group":"データ","fields":["確認した対象範囲","期待件数","除外理由","取得済み件数","未取得","確認不能"],"proposal":"提案：元サービスで本人が確認した対象範囲・期待件数・除外理由と、取得済みデータを照合する。未取得・対象外・確認不能を分け、完全取得と安易に表示しない。","boundary":"権限を越えた取得はしない。期待件数が不明なら完全性を保証しない。"},{"id":"DOT-158","title":"実行課題の受付確認","group":"仕事","fields":["配布元","要求された実行","インストールの要否","独立した依頼者確認","専門家確認","保留理由"],"proposal":"提案：課題の配布元、要求された実行・インストール、独立した依頼者確認、専門家確認の要否を受付票に残す。未確認なら作業開始を保留でき、ファイルやリンクは自動実行しない。","boundary":"マルウェア検査・安全保証はしない。課題や疑わしいリンクの取得・実行はしない。"},{"id":"DOT-159","title":"機器返却前の依存点検","group":"データ","fields":["運用サービス","データの所在","機器と契約","依存関係","移行先","代替稼働確認"],"proposal":"提案：運用サービス、保存データ、利用機器・契約の依存関係を整理し、返却・停止前に移行先と代替稼働の確認を記録する。所有者確認とサービス継続確認を分ける。","boundary":"所有権や契約解除権を判定しない。移行・削除・契約停止の実操作は自動化しない。"},{"id":"DOT-160","title":"仕入条件の比較","group":"商い","fields":["最低金額","数量の倍数","送料条件","必要数の案","条件達成まで増やす案","追加在庫","未確認条件"],"proposal":"提案：仕入先ごとの最低金額・数量倍数・送料条件を使い、必要数だけ買う案と条件達成まで増やす案を比較。追加在庫数、総支出、未確認条件を示し、発注はしない。","boundary":"税・送料・ケース条件は本人が確認。最安や採算を保証せず、自動発注しない。"},{"id":"DOT-161","title":"仕入予算の残枠","group":"商い","fields":["品群","販売期","本人設定の仕入枠","確定発注","未入荷","取消確認済み","未確定見積"],"proposal":"提案：品群・販売期ごとに本人設定の仕入枠、確定発注、未入荷、取消確認済みを並べる予算残枠表。未確定見積は別枠にし、新規買付を加えた残枠を比較する。","boundary":"利益・資金繰りの助言ではない。入力外の契約や請求は捕捉できない。"},{"id":"DOT-162","title":"分納と受入数量の照合","group":"商い","fields":["発注明細","荷物の仮ID","受入数","拒否数","未着数","取消確認済み数"],"proposal":"提案：発注明細を荷物ごとに分け、受入・拒否・未着・取消確認済みの数量を照合。残りの数量が解決するまで発注を閉じず、受入分だけ在庫へ反映する確認票を作る。","boundary":"拒否や取消は実際の相手確認後に手動記録。仕入先への送信はしない。"},{"id":"DOT-163","title":"仕入先の納期観測","group":"商い","fields":["仕入先の仮ID","商品群","約束日と数量","実到着日と受入数量","少件数と季節差"],"proposal":"提案：発注時の約束日・数量と、実到着日・受入数量を蓄積し、仕入先別に遅延幅と未充足を表示。商品群をそろえて比較し、少件数・季節差を明示する。","boundary":"仕入先への一方的な責任認定や信用スコアにしない。"},{"id":"DOT-164","title":"着荷費用の配分案","group":"商い","fields":["荷物の仮ID","確定送料","付帯費用","配分方法","商品別試算","見積原価","未確定費用"],"proposal":"提案：仕入荷物に確定した送料・付帯費用を追記し、本人が選ぶ数量／重量等の配分方法で商品別着荷費用を試算。見積原価との差と未確定費用を分ける。","boundary":"配分は管理用の仮計算。税金・関税を自動算定せず確定値のみ入力。"},{"id":"DOT-165","title":"予約と入荷便の納期確認","group":"商い","fields":["顧客希望","店の確約","未回答","予約数量","入荷予定便","必要な準備と配送時間"],"proposal":"提案：顧客希望・店の確約・未回答を分け、予約数量を入荷予定便に仮引当てする納期確認票。取寄せ・準備・配送所要と便の変更から、影響する注文と不足数を示す。未確定入荷や希望だけを確約へ変えない。","boundary":"配送到着を保証しない。文面は下書きのみで自動送信しない。"},{"id":"DOT-166","title":"委託品の預り精算案","group":"商い","fields":["委託者の仮ID","預り数","販売数","返却数","残数","合意済み手数料","未確認差額"],"proposal":"提案：委託者別に預り・販売・返却・残数を品目で照合し、合意済み手数料と未確認差額を分けた精算明細案を作る。自店所有品と預り品を混ぜず、支払いは行わない。","boundary":"精算額は合意条件の手入力。送金・確定会計・契約締結はしない。"},{"id":"DOT-167","title":"セット構成と作成可能数","group":"商い","fields":["単品またはセットID","構成品","一組の必要数","手入力の受注","利用可能数","不足と未確認"],"proposal":"提案：単品・セット・複数個パックを同じ構成品表に結び、手入力受注を差し引いた作成可能数を計算。構成品不足と未確認を分け、外部在庫の更新は手動確認にする。","boundary":"他販路とのリアルタイム同期なし。実際の売越し防止を保証しない。"},{"id":"DOT-168","title":"商品コードの対応辞書","group":"商い","fields":["基準SKU","仕入先品番","販路商品ID","バーコードの控え","色サイズ","同一・別物・不明"],"proposal":"提案：店内の基準SKUに仕入先品番・販路商品ID・バーコード・色サイズを対応付ける辞書。同じコードの別物、同じ物の重複登録を候補表示し、人が統合を決める。","boundary":"候補一致だけで在庫を合算しない。サイズ・容量違いを手動確認。"},{"id":"DOT-169","title":"入荷から掲載まで","group":"商い","fields":["入荷SKU","掲載先","説明の所在","写真の所在","未確認寸法","販売開始希望","外部掲載確認日"],"proposal":"提案：入荷SKUに掲載先、説明・写真の所在、寸法等の未確認項目、販売開始希望を付ける掲載準備キュー。入荷済み未掲載だけを並べ、外部での掲載確認日を手動記録する。","boundary":"写真本体を大量保存せず所在だけ扱う。自動出品しない。"},{"id":"DOT-170","title":"バリエーションの成立確認","group":"商い","fields":["商品の仮ID","実在する組合せ","販売可","取寄せ","非取扱い","出品案との差"],"proposal":"提案：実在するバリエーションの組合せ表を作り、販売可・取寄せ・非取扱いを区別。商品オプションを手入力した出品案と突き合わせ、成立しない組合せだけ確認する。","boundary":"取寄せ可能性を自動推測せず、確認済み範囲だけ表示。"},{"id":"DOT-171","title":"販路別の販売枠","group":"商い","fields":["SKU","現物確認日","店頭枠","EC枠","取置き","保留","反映時刻と差分"],"proposal":"提案：確認時点の現物数を、店頭・EC・取置き・保留へ手動配分する販売枠表。販路へ反映した時刻と未反映差分を残し、在庫復活は実入荷か確保解除かも分ける。","boundary":"同時受注は検知できない。確認間隔中の販売数は別途照合が必要。"},{"id":"DOT-172","title":"欠品の観測区間","group":"商い","fields":["SKU","販売可能だった日","在庫ゼロの区間","販売終了か入荷待ちか","未観測日"],"proposal":"提案：SKUごとの販売可能だった観測日・在庫ゼロの区間を残し、販売終了品・入荷待ちを区別。売上順位とは別に長い欠品を表示し、欠測日はゼロとして補わない。","boundary":"売れたはずの金額や需要を断定しない。ツールを閉じている間は自動記録しない。"},{"id":"DOT-173","title":"次に数える少数SKU","group":"商い","fields":["選定条件","候補SKU","選定理由","最終実見日","棚卸結果","次の見直し"],"proposal":"提案：過去の差異、補充回数、期限品等の本人が選ぶ条件で、次に数える少数SKUを提示。選定理由と最終実見日を出し、棚卸結果で次の候補を見直す。","boundary":"候補外を正確と保証しない。盗難や担当者の責任を推定しない。"},{"id":"DOT-174","title":"店頭と保管棚の補充","group":"商い","fields":["SKU","店頭の目標数","店頭実見数","バックヤードの所在","補充数","補充後の実見"],"proposal":"提案：店頭の目標数・実見数とバックヤードの所在を持ち、店内移動だけで補える商品をリスト化。仕入不足と店頭補充不足を分け、補充後の実見を記録する。","boundary":"現物数は手動で最新性に限界。複数人同期はしない。"},{"id":"DOT-175","title":"棚容量と分納案","group":"商い","fields":["棚容量","商品寸法","現在数","入荷予定","陳列可能数","保管分","分納案"],"proposal":"提案：本人入力の棚容量・商品寸法・現在数と入荷予定を重ね、陳列に収まる数量と保管へ回る数量を試算。納品量・分納案の比較票を作る。","boundary":"荷重・転倒・避難動線の安全判断はしない。保管可能の保証なし。"},{"id":"DOT-176","title":"商品一覧の並び比較","group":"商い","fields":["用途タグ","価格帯","色","似た商品の隣接","未露出の区分","手動の並び案"],"proposal":"提案：一覧候補に用途・価格帯・色等の本人設定タグを付け、隣接する似た商品と未露出の区分を可視化。売上順と多様性を考慮した手動並び替え案を比較する。","boundary":"顧客を推定属性で分類しない。売上上昇を保証しない。"},{"id":"DOT-177","title":"期限と販売確認日","group":"商い","fields":["表示された期限の原文","納品条件","店の販売確認日","値引き確認日","年月のみか厳密日か","人の判断"],"proposal":"提案：表示された期限、仕入先との納品条件、店が決めた販売・値引き確認日を別管理。期限の近い在庫を並べ、人の判断を記録する。年月表示は勝手に日付へ変換しない。","boundary":"期限延長・販売許可・可食性を自動判断しない。店の確認済み基準だけ使う。"},{"id":"DOT-178","title":"割引条件の架空試算","group":"商い","fields":["対象","併用可否","計算順","最低購入条件","架空カート","適用と除外の理由"],"proposal":"提案：本人入力の割引対象・併用可否・計算順・最低購入条件で、架空カートを試算。適用／除外の理由を示し、店が想定していない組合せを出す。外部設定は変更しない。","boundary":"税・端数・外部ソフト差を保証しない。実注文や決済で試さない。"},{"id":"DOT-179","title":"受渡しの枝別確認","group":"商い","fields":["注文の仮ID","品目数量","持帰り・後日受取・配送","確保品","棚位置","実引渡し","残数"],"proposal":"提案：注文の品目数量を持帰り・後日受取・配送へ分け、確保品・棚位置・期限・準備・実引渡しを照合する受渡し票。枝ごとの残数が解決するまで全体を完了にせず、期限超過も人の確認待ちとする。","boundary":"連絡先は原システム参照。外部注文の分割・返金・送料変更・通知は行わず、本人確認は店の手順で行う。"},{"id":"DOT-180","title":"贈答と荷物の梱包照合","group":"商い","fields":["商品と個数","贈答単位","箱と温度帯","封入物","荷物番号の仮ID","値札と明細の要否"],"proposal":"提案：注文の商品・個数・贈答単位と、箱・温度帯・封入物を一枚の梱包照合票にする。品物→包み→荷物番号を対応付け、値札・納品明細の同封要否も人が確認する。","boundary":"食品安全や輸送耐性を自動判定しない。画像は保存せず所在だけ利用可。"},{"id":"DOT-181","title":"配送条件の候補比較","group":"商い","fields":["確認済み契約条件","寸法","重量","温度帯","補償条件","候補","未確認"],"proposal":"提案：確認済みの配送契約条件と、荷物の寸法・重量・温度帯・補償条件を手入力し、使える候補と未確認条件を比較。本人指定の条件を満たさない安い便は分ける。","boundary":"最新条件は人が公式確認。受付可否・到着日・補償を保証せず予約しない。"},{"id":"DOT-182","title":"運賃明細の照合","group":"商い","fields":["荷物ID","発送時の区分と測定値","見込運賃","請求明細","件数差","追加費用差"],"proposal":"提案：発送時に記録した荷物区分・測定値・見込運賃と請求明細を荷物IDで照合。件数・区分・追加費用の差だけ抽出し、確認用の一覧を作る。支払い・異議送信はしない。","boundary":"未一致を不正請求と断定しない。契約割引・端数・締日の違いを人が確認。"},{"id":"DOT-183","title":"比較価格の根拠","group":"商い","fields":["商品ID","実販売価格","販売期間","メーカー資料の所在","セールで使う比較元","未確認根拠"],"proposal":"提案：商品ごとの実販売価格と販売期間、比較元のメーカー資料所在を記録する価格根拠票。セール案で使う比較元と照合し、根拠未確認を残す。適法性は判定しない。","boundary":"証拠保全・法令遵守を保証しない。必要に応じ専門家へ確認する。"},{"id":"DOT-184","title":"商品説明の主張と根拠","group":"商い","fields":["説明の主張","仕入先資料の所在","版","対象型番","確認日","掲載するか保留か"],"proposal":"提案：商品説明の主張ごとに仕入先資料・版・対象型番・確認日を対応付ける根拠ノート。不明な主張は公開用出力から外す候補として示し、人が掲載を判断する。","boundary":"安全性・効能・適法性を保証しない。根拠資料本文を大量保存しない。"},{"id":"DOT-185","title":"臨時SKUの未解決箱","group":"商い","fields":["仮SKU","数量","品物の所在","対応する正式SKU","在庫減算の確認","二重売上の確認"],"proposal":"提案：臨時販売行に仮SKU・数量・品物の所在を残し、後から正式SKUへ対応付ける未解決箱。在庫減算済みかを照合してから反映し、売上を二重追加しない。","boundary":"実決済・税区分・レジ訂正は行わない。原取引の参照番号だけ保持。"},{"id":"DOT-186","title":"設定の根拠台帳","group":"創作","fields":["人物・場所・規則のID","短い設定事実","初出の巻章場面","確定か仮案か","例外","矛盾候補"],"proposal":"提案：設定根拠台帳。人物・場所・規則を短い事実単位で登録し、初出の巻・章・場面、確定／仮案、例外を並べて人が矛盾を照合する。","boundary":"自動で矛盾と断定しない。本文全文は保存せず作者入力の要点のみ。"},{"id":"DOT-187","title":"作中と掲載の二重時系列","group":"創作","fields":["場面ID","作中日時の原文","作中順の番号","掲載順の番号","期間","回想と同時進行","年齢の前提"],"proposal":"提案：二重時系列表。場面に作中日時・期間と掲載順を別登録し、同時進行、回想、年齢計算の前提を並列表示する。","boundary":"架空暦や曖昧な期間を西暦に強制変換しない。"},{"id":"DOT-188","title":"仕込みと回収の対応","group":"創作","fields":["仕込み場面ID","期待させた問い","回収場面ID","未回収か意図的余白か","終稿前の確認"],"proposal":"提案：仕込み・回収対応表。提示場面、期待させた問い、回収場面、未回収／意図的余白を結び、終稿前の確認一覧を出す。","boundary":"曖昧な結末を欠陥判定しない。作品外への自動公開はしない。"},{"id":"DOT-189","title":"作品スタイルシート","group":"創作","fields":["採用表記","別表記","数字の方針","約物の方針","心内語の方針","例外箇所"],"proposal":"提案：作品スタイルシート。採用表記と別表記、数字・約物・心内語等の組版方針、例外箇所を記録し校正用の判断表にする。","boundary":"創作上の崩しや話者固有表現を一括置換しない。"},{"id":"DOT-190","title":"着想の保育箱","group":"創作","fields":["断片","きっかけ","惹かれた理由","用途未定のまま残すこと","関心タグ","掘り返す条件"],"proposal":"提案：着想の保育箱。断片・発生のきっかけ・惹かれた理由を短く記録し、未所属のまま保管、似た関心や放置期間から手動で掘り返す。","boundary":"創作価値を点数化せず、引用は出典と短い要約のみ。"},{"id":"DOT-191","title":"構成案の比較盤","group":"創作","fields":["案の名前","場面IDの並び","各場面の前提","各場面の結果","変更理由","採否"],"proposal":"提案：構成案の比較盤。本文を複製せず場面IDの並びを複数案で保存し、各場面の前提・結果と合わせて変更案を比較する。","boundary":"自動で本文を移動しない。因果の良し悪しは作者が判断する。"},{"id":"DOT-192","title":"校正と校聴の戻し照合","group":"創作","fields":["基準版","頁行または時刻","短い目印","指摘","採否","反映先版","再確認"],"proposal":"提案：校正・校聴戻し照合票。基準版と頁・行または時刻、短い目印、指摘・採否、反映先版を記録し、反映と再確認を別状態にする。音声は差替え素材と前後の再聴結果も残す。","boundary":"原稿や音声を自動更新しない。基準版が変われば要再確認とし、長文・音声そのものの保存は不要。"},{"id":"DOT-193","title":"試読反応の論点地図","group":"創作","fields":["場面ID","読者の反応","根拠","提案","作者の狙い","採否と理由"],"proposal":"提案：試読反応の論点マップ。場面単位で読者の反応・根拠・提案を分離し、作者の狙いと照らして採用／保留／不採用理由を残す。","boundary":"試読者の実名・連絡先は不要。評価の正誤や人格を採点しない。"},{"id":"DOT-194","title":"参照したい要素の束","group":"創作","fields":["画像などの所在","出典","注目部位","使いたい要素","用途タグ","作品ID"],"proposal":"提案：参照目的カード。画像を格納せず所在・出典と、注目部位、使いたい要素、用途別タグを複数付け、作品の参照束を作る。","boundary":"参照は転載許可ではない。権利確認済みという誤表示をしない。"},{"id":"DOT-195","title":"入稿ページの対応","group":"創作","fields":["予定順","ファイル名","表紙・本文・空白頁","ノンブル","見開き左右","確認印"],"proposal":"提案：入稿ページ対応表。表紙・本文・空白頁を含む予定順、ファイル名、ノンブル、見開き左右を一列ずつ照合して確認印を残す。","boundary":"実ファイルの自動検査を装わない。無ノンブル頁や右綴じを許容する。"},{"id":"DOT-196","title":"試刷りの比較","group":"創作","fields":["試刷りID","紙と厚さ","仕上げ","色と透け","照明条件","採用理由"],"proposal":"提案：試刷りの表現比較票。紙名だけでなく厚さ・仕上げ・確認した色や透け、照明、採用理由を作品の試刷りIDごとに記録する。","boundary":"画面上の色から印刷結果を保証しない。現物見本は別保管する。"},{"id":"DOT-197","title":"用途別の出力検品","group":"創作","fields":["提出先仕様と版","出力物版","寸法と塗り足し","形式","音声の測定条件","確認値","未測定"],"proposal":"提案：用途別出力検品票。提出先仕様・版と出力物版を対にし、形式別に寸法・塗り足し・形式、音声なら測定範囲・メーター・ラウドネス・True Peak等を人が照合する。確認済み値と未測定を分ける。","boundary":"PDF解析・音声解析・正規化を自動実行せず、受理や適合を保証しない。閾値は対象先の現行仕様を人が確認する。"},{"id":"DOT-198","title":"作品・版・形式の書誌","group":"創作","fields":["題名","言語","改訂内容","媒体","取得済みISBN","確認元"],"proposal":"提案：作品―版―形式台帳。題名、言語、改訂内容、媒体を分け、取得済みISBNと確認元を登録して各出力版の書誌票を作る。","boundary":"ISBNを自動発行・流用判断しない。確認済み識別子の記録だけ。"},{"id":"DOT-199","title":"EPUB目次の照合","group":"創作","fields":["EPUB2か3か","章ファイル","見出し階層","目次リンク先","実機条件","確認結果"],"proposal":"提案：EPUBナビ照合票。EPUB2／3を明示し、章ファイル・見出し階層・目次リンク先・実機確認結果を対応させ、未確認リンクを一覧化する。","boundary":"ファイルを自動解析せず、実機・ソフト版と未試験を明示する。"},{"id":"DOT-200","title":"挿絵の意味と代替文","group":"創作","fields":["配置箇所","役割","本文との関係","代替文","別掲キャプション","長文説明の要否"],"proposal":"提案：挿絵の意味台帳。配置箇所ごとに役割、本文との関係、代替文、別掲キャプション、要長文説明を分け、書き出し担当の確認用にまとめる。","boundary":"自動生成文を正解扱いしない。装飾判定は配置文脈ごとに行う。"},{"id":"DOT-201","title":"利用しやすさ説明の根拠","group":"創作","fields":["版","確認済み機能","未対応箇所","試験条件","人が確認した説明文"],"proposal":"提案：アクセシビリティ説明の根拠表。版ごとに確認済み機能・未対応箇所・試験条件を記録し、accessibilitySummary用の人手確認済み説明文を組む。","boundary":"未試験を対応済みに変換しない。規格名・版・対象版を明示する。"},{"id":"DOT-202","title":"素材利用とクレジット","group":"創作","fields":["入手元","権利者の記載","ライセンス名と版","記載条件","変更内容","使用先","出典表示案"],"proposal":"提案：素材利用・クレジット票。素材ごとに入手元、権利者、ライセンス名・版、記載条件、変更内容、使用先を結び、出典表示の下書きを作る。","boundary":"利用可能と自動判定しない。転載・改変等の不明条件は確認待ちとする。"},{"id":"DOT-203","title":"公開許諾の適用範囲","group":"創作","fields":["自作要素ID","第三者要素ID","選んだ許諾","適用範囲","除外要素","告知文の下書き"],"proposal":"提案：公開許諾の範囲図。自作部分と第三者部分を要素IDで分け、選んだライセンスの適用範囲と除外要素を示す告知文の下書きを作る。","boundary":"自動公開・自動ライセンス付与をしない。所有権の証明機能ではない。"},{"id":"DOT-204","title":"公開と権利の履歴","group":"創作","fields":["初出媒体と日付","契約の参照位置","言語の対象範囲","形式の対象範囲","地域の対象範囲","再利用確認日"],"proposal":"提案：作品の公開・権利履歴。初出媒体と日付、取得した契約の参照位置、言語・形式・地域別の対象範囲、再利用確認日を記録し再録用の確認票にする。","boundary":"契約全文や相手の個人情報は保管不要。期限経過だけで権利回復と断定しない。"},{"id":"DOT-205","title":"ショットのつながり","group":"創作","fields":["作中日","直前と直後のカット","物の位置","衣装","動作の到達点","参考静止画の所在"],"proposal":"提案：ショットつながり票。作中日と直前・直後カット、物の位置、衣装、動作・感情の到達点、参考静止画の所在を記録し再撮影前に照合する。","boundary":"静止画は所在のみで容量を抑える。意図した不連続を誤り扱いしない。"},{"id":"DOT-206","title":"スレートとテイクの索引","group":"創作","fields":["シーン","ショット","テイク","カメラ素材名","音声素材名","同期の区分","採用候補"],"proposal":"提案：スレート・テイク索引。シーン、ショット、テイク、カメラ素材名、音声素材名、同期／別録り／ガイド、採用候補を一対多で対応させる。","boundary":"自動同期やファイル読み取りを装わない。同名素材は一意IDで区別。"},{"id":"DOT-207","title":"撮影できた要素の照合","group":"創作","fields":["シーン","必要な台詞","動作","つなぎ要素","使えるテイクの範囲","不足部分"],"proposal":"提案：撮影カバレッジ表。シーンの必要な台詞・動作・つなぎ要素と、使えるテイクの範囲を対応させ、不足部分だけを再撮影候補へ出す。","boundary":"美的な十分さを自動判定しない。安全な撮影の助言機能ではない。"},{"id":"DOT-208","title":"編集素材の依存索引","group":"創作","fields":["編集内の呼称","元ファイル名","旧所在","識別情報","使用作品","再接続確認"],"proposal":"提案：素材依存索引。編集内の呼称、元ファイル名・旧所在、媒体開始値等の識別情報、使用作品を記録し、移動後は候補照合と再接続確認を残す。","boundary":"パスだけでは同一性を保証しない。実ファイルの一括移動・再接続はしない。"},{"id":"DOT-209","title":"朗読の読みと声の決定","group":"創作","fields":["語または人物","表記","読み","アクセントの説明","決定根拠","参照音声の所在","適用章"],"proposal":"提案：朗読の読み・声の決定表。語・人物ごとに表記、読み、アクセントの説明、決定根拠、参照音声の所在、適用章を記録して収録前に確認する。","boundary":"方言や発音の唯一の正解を断定しない。音声実体は保存しない。"},{"id":"DOT-210","title":"画像内文字の可読性","group":"創作","fields":["図中文字の有無","本文として出せる部分","確認した画面幅","拡大条件","読みにくい箇所","代替説明"],"proposal":"提案：電子版の画像可読性票。図中文字の有無、本文として出せる部分、確認した画面幅・拡大条件、読みにくい箇所と代替説明の対応を記録する。","boundary":"自動で読めると保証しない。スクリーン画像を大量保存しない。"},{"id":"DOT-211","title":"文字起こしと字幕の校閲","group":"創作","fields":["出現時刻","正表記","誤記候補","話者と文脈","重要音","聞き直し","字幕の開始と終了"],"proposal":"提案：音声文字化・字幕校閲票。出現時刻、正表記と誤記候補、話者・文脈、重要音、聞き直し状態を結ぶ。字幕では開始終了・改行・時刻逆転も確認し、字幕を作らない文字起こしでも使えるようにする。","boundary":"自動音声認識・一括確定は行わない。同音別語を文脈で確認し、演出上必要な字幕重複を許容する。"},{"id":"DOT-212","title":"音声解説の挿入設計","group":"創作","fields":["視覚情報の時刻","重要性","既存音声で分かるか","候補文","発話できる間","通常版か拡張版か"],"proposal":"提案：音声解説キュー設計。視覚情報の時刻・重要性・既存音声で分かるか、候補文、発話可能な間、通常／拡張版の判断を記録する。","boundary":"解説を自動生成せず、登場人物の心情を事実として補完しない。"},{"id":"DOT-213","title":"説明的トランスクリプト","group":"創作","fields":["場面順","発話","意味のある音","視覚説明","編集者補足","見出しと話者"],"proposal":"提案：説明的トランスクリプト編集票。発話・意味のある音・視覚説明・編集者補足を区別し、場面順で見出しと話者を整えた文章版を作る。","boundary":"補足を出演者の発言として書かない。翻訳や情報の正確さを保証しない。"},{"id":"DOT-214","title":"請求名と解約先の対応","group":"生活","fields":["明細の請求名","サービス名","購入経路","解約画面の所在","終了予定","終了の実確認"],"proposal":"提案：請求名→サービス名→購入経路→解約する画面の対応表。解約申出・終了予定・終了確認を分け、明細の不明名を未照合箱へ置く。番号やログイン情報は保存しない。","boundary":"個人名・認証情報・口座番号は不要。記録と照合のみで、送信・申請・契約変更・法的判断は行わない。"},{"id":"DOT-215","title":"契約の枝を分ける","group":"生活","fields":["契約本体","別会社オプション","貸出機器","契約先の役割","支払条件","継続または終了の希望"],"proposal":"提案：一度の申込みを契約本体・別会社オプション・貸出機器へ分解する「契約の枝」。各枝の契約先、支払条件、継続／終了希望を別管理し、本体終了で他の枝を消さない。\n統合した関連工程：提案：現在の回線・プロバイダ・請求会社と、勧誘者・新契約会社・工事会社を別枠で並べる。説明と届いた書面の違い、残る旧契約を手動確認し、不明な関係は線を確定しない。","boundary":"個人名・認証情報・口座番号は不要。記録と照合のみで、送信・申請・契約変更・法的判断は行わない。"},{"id":"DOT-216","title":"返品と定期終了の二工程","group":"生活","fields":["返品承諾","返送控え","定期契約の終了申出","終了確認","残っている工程"],"proposal":"提案：「商品を戻す」と「次回以降を止める」を二本の工程に分け、返品承諾・返送控え・定期契約の終了確認を結ぶ。片方だけ終わった時は残る工程を表示する。","boundary":"個人名・認証情報・口座番号は不要。記録と照合のみで、送信・申請・契約変更・法的判断は行わない。"},{"id":"DOT-217","title":"期間と窓口時間の照合","group":"生活","fields":["契約に書かれた期間","窓口時間","連絡を試した日時","手段と結果","証跡の所在","窓口変更の説明"],"proposal":"提案：「解約できる期間」と「窓口が開く時間」を別登録し、連絡を試した日時・手段・結果・証跡の所在を時系列化。窓口変更の説明も残し、相談先へ持参する一枚を出す。","boundary":"個人名・認証情報・口座番号は不要。記録と照合のみで、送信・申請・契約変更・法的判断は行わない。"},{"id":"DOT-218","title":"保証の使い道比較","group":"生活","fields":["メーカー保証","販売店保証","対象外項目","原因未確認","見積と送料","本人の修理判断"],"proposal":"提案：故障した品にメーカー保証・販売店保証の条件と対象外項目を並べ、原因未確認・見積・送料等の別費用・本人の修理判断を記録する「保証の使い道票」。期限内だけで無償と表示しない。","boundary":"個人名・認証情報・口座番号は不要。記録と照合のみで、送信・申請・契約変更・法的判断は行わない。"},{"id":"DOT-219","title":"同じ箇所の前後比較","group":"生活","fields":["箇所ID","預ける前の状態所在","途中の連絡","返却後の状態所在","明細の対象箇所","説明待ち"],"proposal":"提案：部屋の同じ箇所IDに入居時・途中の不具合連絡・退去時の写真所在を並べる。請求明細の対象箇所と対応付け、撮れていない箇所や説明待ちだけ確認票へ。\n統合した関連工程：提案：衣類の部分IDに預ける前の染み・ボタン・付属品と、返却直後の確認を対にする。依頼した処置と戻った状態、業者回答を並べ、洗濯済みと状態確認済みを分離する。","boundary":"個人名・認証情報・口座番号は不要。記録と照合のみで、送信・申請・契約変更・法的判断は行わない。"},{"id":"DOT-220","title":"見積と直前実数の差","group":"生活","fields":["申告した品目と箱数","直前の実数","追加と除外","未採寸","搬出入条件","付帯作業","再確認した版"],"proposal":"提案：見積時に申告した家具・箱数と直前の実数を並べ、追加・除外・未採寸を差分化。搬出入の階段や経路条件を同じ申告票へ結び、業者に再確認した版を残す。\n統合した関連工程：提案：引越し本体とエアコン等の付帯作業を分け、取外し・運送・取付けの日と各業者、基本料／条件付き追加料／未確定を横並びにする。比較時は未確定額をゼロにしない。\n統合した関連工程：提案：品目・量・搬出階・分解の有無と、回収対象外／追加条件／見積の有効範囲を対応させる。自治体で確認した業者情報の所在も記録し、当日変更分を前の見積と対比する。\n統合した関連工程：提案：家族が希望した規模、プラン内の品目、追加された品目、数量未定の費用を分離。見積りの版ごとに追加・置換・数量差を示し、打合せで尋ねる未確認項目を印刷する。","boundary":"個人名・認証情報・口座番号は不要。記録と照合のみで、送信・申請・契約変更・法的判断は行わない。"},{"id":"DOT-221","title":"搬入と開梱検品の区別","group":"生活","fields":["品物の仮ID","搬出前の状態","到着後の状態","開梱日","事業者への連絡控え","未開梱"],"proposal":"提案：搬入済みと開梱検品済みを分ける。壊れやすい品ごとに搬出前・到着後の状態、開梱日、事業者への連絡控えを結び、未開梱の高優先品を次の一箱に出す。","boundary":"個人名・認証情報・口座番号は不要。記録と照合のみで、送信・申請・契約変更・法的判断は行わない。"},{"id":"DOT-222","title":"必要日から試運転へ","group":"生活","fields":["候補","必要日","確約納期","見込納期","初期設定の日数","返品条件","試運転確認"],"proposal":"提案：購入候補に必要日、確約納期／見込納期、初期設定に要る日数、返品条件を置く。必要日から試運転日を逆算し、「届くが使えるか未確認」を別表示する。","boundary":"個人名・認証情報・口座番号は不要。記録と照合のみで、送信・申請・契約変更・法的判断は行わない。"},{"id":"DOT-223","title":"返金の四段確認","group":"生活","fields":["注文総額","返金を求めた額","相手の回答額","実際の返金額","約束日","残額の確認"],"proposal":"提案：注文総額、返金を求めた額、相手の回答額、実際に確認した返金額を四段で表示。約束日と残額を結び、返金の連絡が来ただけでは完了にしない。","boundary":"決済・口座接続なし。カード番号や口座番号は保存せず、返金を口実に別送金を要求する相手へ誘導しない。正規の相談窓口確認を促す。"},{"id":"DOT-224","title":"契約の存在索引","group":"生活","fields":["サービス名","利用目的","契約資料の保管先","本人が望む方向","公式窓口の確認日"],"proposal":"提案：秘密を入れない「契約の存在索引」。サービス名、利用目的、契約確認資料の保管先、本人が望む終了／相談の方向、公式の死亡時窓口確認日を記録し、選んだ項目だけ紙へ。","boundary":"パスワード・PIN・秘密鍵・残高・口座番号は保存しない。本人の意思と家族の判断を区別し、相続権や代理権を判定しない。"},{"id":"DOT-225","title":"勤務の切替と未確認区間","group":"生活","fields":["退職日","新勤務開始日","窓口で確認した年金の状態","健康保険の状態","証明の発行待ち","配偶者側への確認"],"proposal":"提案：退職日と新勤務開始日の間を区間化し、本人が窓口で確認した年金・健康保険の状態、必要証明の発行待ち、配偶者側への確認の有無を並べる。日程変更で未確認区間だけ戻す。","boundary":"基礎年金番号・保険証画像・医療情報は保存不要。制度適用・保険料・免除可否は窓口確認し、ツールで判断しない。"},{"id":"DOT-226","title":"有償回数と利用履歴","group":"生活","fields":["広告の利用可能期間","契約上の有償回数","有償期間","無償部分","実利用回数","支払残"],"proposal":"提案：広告上の利用可能期間、契約上の有償回数・期間、無償部分、実利用回数を別に並べる。支払い残と未利用回数を混ぜず、解約相談用に契約記載と利用履歴を結ぶ。","boundary":"施術内容・身体写真・診断は保存不要。返金可能額や合法性を自動判定しない。利用回数と契約原文の所在だけを扱う。"},{"id":"DOT-227","title":"券の期限と払戻申出","group":"生活","fields":["券面期限の原文","公式の利用終了告知","払戻申出期間","保管場所","申出控え","返金確認"],"proposal":"提案：商品券の券面期限と、発行者が知らせる利用終了・払戻申出期間を別管理。確認した公式告知、券の保管場所、申出控え、返金確認を結び、期限記載なしを永久利用可と扱わない。","boundary":"券番号や利用可能コードは保存しない。払戻申請・送金はせず、各発行者の現行案内を本人が確認する。"},{"id":"DOT-228","title":"故障時の相談と作業承諾","group":"生活","fields":["平時に確認した相談順","連絡先の参照元","出張と点検料金","作業と部品料金","キャンセル料","見積依頼か施工承諾か"],"proposal":"提案：平時に管理会社・自治体等で確認した相談順と連絡先の参照元を用意。故障時は出張・点検・作業・部品・キャンセル各料金の確認欄へ切替え、見積だけの依頼と施工承諾を分ける。","boundary":"修理・解錠の技術手順は出さない。安全緊急対応を妨げず、業者の適法性を自動保証しない。ツールを開けない時の紙を準備する。"},{"id":"DOT-229","title":"申告資料の保管確認","group":"データ","fields":["原本・印刷・領収書・補完の区分","資料の所在","提出時の扱い","紙封筒の所在","確認先"],"proposal":"提案：申告に使った資料を、通知データ原本・通知の印刷・領収書・補完分に分類。提出時の扱いと紙封筒の所在を結び、画像があるだけで原本不要としない保管確認票を作る。","boundary":"病名・診療内容・個人番号・画像本体は保存不要。保管要否は現行制度と本人確認で確定し、廃棄を自動実行しない。"},{"id":"DOT-230","title":"補填見込と確定の差","group":"生活","fields":["費用束の匿名ID","申告で使った見込額","後日確定額","確認資料の所在","対象年","税務確認待ち"],"proposal":"提案：匿名の費用束IDに申告で使った補填見込額・後日確定額・確認資料所在を結ぶ。差がある束だけ税務確認待ちへ戻し、今年の入金と対象年の費用を混同しない。","boundary":"医療詳細を持たず費用束IDだけ。申告額の決定・税務申告・保険請求を自動化せず専門窓口へ確認。"},{"id":"DOT-231","title":"注文案と最終画面の照合","group":"生活","fields":["最初の商品と個数","最終の商品と個数","単発か定期か","最低回数","次回金額","追加か置換か"],"proposal":"提案：最初の注文案と最終確認画面の手入力控えを、商品・個数・定期か単発か・最低回数・次回金額で照合。追加か置換か未確認の時は別注文を自動統合せず、確認項目を出す。","boundary":"個人名・認証情報・口座番号は不要。記録と照合のみで、送信・申請・契約変更・法的判断は行わない。"},{"id":"DOT-232","title":"取込仕様の変更確認","group":"データ","fields":["前月の列名と単位","前月の必須欄","今回の列名と単位","新設と消失","意味変更の疑い","対応表の再使用確認"],"proposal":"提案：取込仕様の変更ゲート。前月の列名・単位・必須欄と今回を並べ、新設／消失／意味変更疑いだけを確認してから既存対応表を再使用する。","boundary":"ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-233","title":"競合する値の保留箱","group":"データ","fields":["対象と項目","適用期間","元の値","別の値","採用値","確認根拠","保留理由"],"proposal":"提案：値の競合保留箱。同じ対象・項目・適用期間に異なる値が来たら両方を保ち、採用値・確認根拠・保留を選んでから報告へ反映する。","boundary":"ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-234","title":"似ているが別物の辞書","group":"データ","fields":["候補A","候補B","同一・別物・不明","判断理由","文脈の変更","再確認"],"proposal":"提案：「似ているが別物」辞書。統合候補に同一／別物／不明と理由を残し、次回取込で既知の別物を再提案しない。対象の文脈が変われば再確認する。","boundary":"人の同一性を氏名だけで判定しない。 ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-235","title":"ID付きの訂正差戻し","group":"データ","fields":["安定ID","元値","新値","現在値との一致確認","不一致の保留","反映の実確認"],"proposal":"提案：ID付き修正差戻し。元値・新値・安定IDを小さな訂正表にし、元値が今も一致する行だけ反映候補へ。並べ替え後でも対象を照合し、不一致は保留する。","boundary":"ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-236","title":"明細と小計の階層","group":"データ","fields":["元の行ID","明細・小計・総計・注記","原値","明細の集計値","小計との照合","分類の確認"],"proposal":"提案：明細・小計の階層札。取込行を明細／小計／総計／注記へ人が分類し、集計には明細だけを使い、小計は照合用として保持する。","boundary":"ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-237","title":"比較の母集団しおり","group":"データ","fields":["対象期間","採用行ID","除外理由","集計ルール版","対象変更分","同条件の変化"],"proposal":"提案：比較の母集団しおり。対象期間、採用行ID、除外理由、集計ルール版を結果と一緒に保存し、翌月比較時に対象変更分と同条件の変化を分ける。","boundary":"ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-238","title":"空欄理由と分母の確認","group":"データ","fields":["対象項目","値","未回答・未確認・対象外・測定なし","集計の分母","不足件数","出力条件"],"proposal":"提案：空欄理由レイヤー。未回答／未確認／対象外／測定なしを値とは別に保持し、集計ごとの分母と不足件数を確認してから出力する。","boundary":"ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-239","title":"再使用前の鮮度確認","group":"データ","fields":["対象項目","適用期間","確認日","本人設定の見直し条件","元表の範囲と基準日","出力先と固定した値","再確認が必要な値"],"proposal":"提案：再使用前の鮮度ゲート。項目に適用期間と確認日・本人設定の見直し条件を付け、資料再作成時に期限を過ぎた値だけ再確認する。\n統合した関連工程：提案：数字の凍結時点札。元表の範囲・基準日・出力先・リンク／静的／手転記を持ち、提出済み資料はその時点の値として固定。再利用時だけ鮮度確認を促す。","boundary":"ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。\n統合した関連工程：数値を勝手に最新値へ置換しない。元表の機密データを複製しない。"},{"id":"DOT-240","title":"日付移行の基準点照合","group":"データ","fields":["原表で確認した日付","移行後の日付","日付のずれ","方式の確認先","不明な方式の保留","予定への登録確認"],"proposal":"提案：日付移行の基準点照合。原表で人が確認した日付を数件アンカーとして置き、移行後の日付とのずれが一定かを確認し、方式不明なら予定へ登録しない。","boundary":"1462日差を見つけても自動補正しない。 ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-241","title":"量の意味付き比較","group":"データ","fields":["対象の数値","単位","基準量","対象期間","税込などの条件","換算根拠","未比較の理由"],"proposal":"提案：量の意味付き比較カード。数値に単位・基準量・対象期間・税込等の本人定義条件を付け、条件がそろう項目だけ比較表へ移す。換算根拠不明は未比較とする。","boundary":"ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-242","title":"時間表記と時間量の仕分け","group":"データ","fields":["元表記","開始時刻","終了時刻","経過分","小数時間","工数へ渡す値"],"proposal":"提案：時刻と時間量の仕分け。取込列を開始時刻／終了時刻／経過分／小数時間として確認し、元表記と計算値を対照して工数枠へ渡す。","boundary":"ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-243","title":"端数差の説明","group":"データ","fields":["明細の原値","行ごと丸めの条件","合計後丸めの条件","出力された合計","一致した方式","未説明差額"],"proposal":"提案：端数差の説明器。行ごと丸め／合計後丸めの条件を並列試算し、出力された合計と一致する方式・未説明差額を記録する。","boundary":"税務・会計ルールの正しさは判定しない。 ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-244","title":"原表記と提出先表記","group":"データ","fields":["原表記","提出先","確認した代替表記","確認方法","用途","次回選び直す点"],"proposal":"提案：原表記・提出先表記の対照カード。原表記を変えず、提出先で本人が確認した代替表記・確認方法・用途を別に保存し、次回記入時に選び直す。","boundary":"身元照合・戸籍上の正字判定はしない。 ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-245","title":"回答変更の依存再点検","group":"段取り","fields":["前提回答","本人が転記した分岐条件","依存する回答","必要添付","再確認する範囲"],"proposal":"提案：回答変更の依存再点検。本人が転記した分岐条件に従い、前提回答を変えたら依存する回答・添付の準備状態だけを再確認へ戻す。","boundary":"申請資格や適法性は判定しない。条件の正しさは原案内で本人が確認。 ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-246","title":"提出先別の短縮版","group":"連絡","fields":["原文の所在","残す要点","提出先の文字上限","残した要点","削った要点","確認した短縮文"],"proposal":"提案：提出先別の短縮版編集。原文の要点に印を付け、各上限の版へ残した／削った要点を対応させる。制限だけ満たして重要条件が消えていないか確認する。","boundary":"自動要約で新たな主張を足さず、文字の数え方は提出先で確認する。 ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-247","title":"外部フォームの下準備","group":"連絡","fields":["質問","回答素材","必要資料","根拠日と有効期間","使う目的","未確認の問い","コピーする束"],"proposal":"提案：外部フォームの下準備台。本人が質問と必要資料だけを持込み、時間制限なしで回答を整え、質問順の一時コピー用束と未確認一覧を作る。送信操作は外部で本人が行う。\n統合した関連工程：提案：回答素材の有効期間箱。業務紹介・活動実績など本人作成の回答を根拠日・対象期間・使用目的とともに保存し、別の申込への転用時に有効性と質問への適合を確認する。\n統合した関連工程：提案：反復回答の組立て台。各経歴・案件に仮IDを付け、質問群を一組として並替え・除外し、件数と質問ごとの未回答を見てから順番にコピーする。","boundary":"アクセス・自動入力・ログイン連携なし。クリップボードへ自動コピーせず機微情報は使わない。 ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。\n統合した関連工程：W3Cの同一工程基準を複数申込間の要件へ一般化しない。パスワード等は対象外。 ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-248","title":"聞く理由から作る受付票","group":"連絡","fields":["質問","後工程での用途","使い道がない質問","他項目から分かる質問","紙票の案","処理手順"],"proposal":"提案：「聞く理由」から作る受付票。質問と後工程の用途を結び、使い道がない質問・既に別項目から分かる質問を候補表示。必要最小限の紙票と処理手順を同時に出す。","boundary":"実顧客情報を入れず空テンプレだけで検証する。 ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-249","title":"複製文書の変数確認","group":"データ","fields":["原文の所在","日時の変数","会場の変数","金額の変数","年度の変数","今回の根拠","未確認の旧値"],"proposal":"提案：複製文書の変数監査。前回の日時・会場・金額・年度を変数として印付けし、複製時に確定／据置確認／未確認へリセット。旧値が残る出力箇所を一覧にする。\n統合した関連工程：提案：「前回から使える部分だけ」。定例作業の文章・対象期間・数値・根拠所在を別欄化し、コピー時に構造だけ継承、前回値は参照表示に留める。今回の根拠を入れた欄だけ確認済みにする。","boundary":"ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。\n統合した関連工程：業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-250","title":"版の枝と比較元の確認","group":"データ","fields":["受信原本ID","どの版から直したか","編集コピーID","返送候補ID","共通元版","採用確認","未確認の比較"],"proposal":"提案：比較ペアの来歴確認。受け取った版に「どの版から直したか」「確認済みか」を手動登録し、共通元版のない比較や採用済みより古い派生版を注意表示する。\n統合した関連工程：提案：添付から返送までの枝分かれ票。受信添付ID→編集コピー→返送候補を結び、同名でも親子を分ける。『受信原本を選んでいる』場合は本人に確認を促す。","boundary":"法的証跡・電子署名・本人性の保証なし。 ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。\n統合した関連工程：内容自動読取・クラウドへのアップロードは不要。誤りと断定せず意図した原本返送も選べる。"},{"id":"DOT-251","title":"表の文脈付き読取","group":"データ","fields":["元の位置","対象","期間","項目","単位","値","表頭と表側の確認"],"proposal":"提案：表の文脈付き読取カード。本人が表頭・表側の対応を確認し、選んだセルを「対象・期間・項目・単位・値」の一組で読む／印刷する。元の位置へ戻れる。","boundary":"自動OCRや見出し推測に頼らず、人の確認なしに意味を確定しない。基本アクセシビリティを課金壁にしない。 ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-252","title":"整形レシピの試験札","group":"データ","fields":["変換の説明","正常例","変換しない例","想定結果","今回の結果","失敗時の保留"],"proposal":"提案：整形レシピの試験札。自分が決めた変換に正常例・変換しない例・想定結果を数件添え、レシピ変更や月次利用前に架空例で結果比較する。失敗時は本データ適用を保留する。","boundary":"任意コードの実行は不要とし、限定された宣言的操作だけを対象にする。 ローカルの手動取込・確認用出力に限定。外部同期・送信・原本書換えはしない。R54/R55修正検証前は架空データのみ。"},{"id":"DOT-253","title":"成果物と複数の作業枠","group":"段取り","fields":["成果物ID","完了条件","締切","今回進める範囲","作業結果","残る範囲"],"proposal":"提案：「成果物ひとつ・作業枠いくつか」。成果物の完了条件と締切を一つだけ持ち、複数枠に今回進める範囲と実施結果を結ぶ。枠を消化しても成果物を完了にせず、残りの範囲を次枠へ渡す。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-254","title":"時刻を決めない時間かご","group":"段取り","fields":["使える総時間","日付未定の作業","短めの所要","通常の所要","長めの所要","未見積","配置の候補"],"proposal":"提案：「時刻を決めない持ち時間かご」。本人が使える総時間だけを入れ、日付未定・所要時間幅付き作業を仮配置。時刻を決めず不足幅と未見積項目を示し、後で既存カレンダーへ手動配置する。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-255","title":"今日の残りを組み直す","group":"休息","fields":["中断後の残時間","固定約束","継続する作業","短縮案","別日相談","移動前後の比較"],"proposal":"提案：「今日の残りを組み直す差分」。中断後の残時間と固定約束を残し、移せる作業だけを継続・短縮案・別日相談へ分ける。移動前後と相談が必要な約束を並べ、人が確定する。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-256","title":"見積時間の条件メモ","group":"段取り","fields":["対象作業","短めの所要","通常の所要","長めの所要","初回や再利用の条件","同条件の実績","条件不一致"],"proposal":"提案：「見積の条件メモ」。所要を一点でなく短め・通常・長めの幅で登録し、初回／再利用あり／確認待ち等の条件と結ぶ。実績後は同条件の過去例だけを次回候補に出し、条件不一致は目立たせる。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-257","title":"分解前の偵察枠","group":"段取り","fields":["本人指定の時間枠","確かめる一問","成果物の見本所在","確認結果","分解・人に聞く・まだ不明","次の工程"],"proposal":"提案：「分解する前の偵察枠」。最初から全工程を作らず、10分等の本人指定枠で確かめる一問と成果物の見本所在だけを置く。結果を受け、分解できる／人に聞く／まだ不明へ分けて次工程を作る。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-258","title":"わかった・まだ不明の進捗","group":"調査","fields":["調査目的","問い","回答あり","否定できたこと","資料不足","消えた不明点","次の一問"],"proposal":"提案：「わかった・まだわからない進捗」。調査目的に問いを結び、回答あり・否定できた・資料不足を分離。毎回の作業枠には消えた不明点と次に調べる一問だけを引き継ぐ。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-259","title":"判断に足りるところまで","group":"調査","fields":["決めたいこと","必要な根拠","今回は調べない範囲","次の見直し条件","根拠の所在","追加調査で変わること"],"proposal":"提案：「この判断に足りるところまで」。調査開始時に決めたいこと・必要な根拠・今回は調べない範囲・次の見直し条件を記録。根拠を紐付けたら終了候補を表示し、追加検索は何を変えうるかを一行で確かめる。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-260","title":"調べたが使わなかった道","group":"調査","fields":["問い","検索語","見た出典の所在","不採用理由","再確認する条件","既調査と未調査の境界"],"proposal":"提案：「調べたけれど使わなかった道」。問いごとに検索語・見た出典の所在・不採用理由・再確認が必要になる条件を短く残す。同じ問いに戻った時、採用資料より先に既調査と未調査の境界を表示する。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-261","title":"問いと根拠の組合せ","group":"調査","fields":["問い","短い自分のメモ","出典の所在","支持する点","反対する点","条件の違い","未解決の食違い"],"proposal":"提案：「問いと根拠の組み合わせ台」。短い自分のメモに出典所在を付け、同じ問いの支持・反対・条件違いを並列表示。どの根拠からどこまで言えるかを結び、文章化後も未解決の食違いを残す。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-262","title":"返事と回答充足を分ける","group":"連絡","fields":["質問の小項目","受信した事実","回答済み項目","残る問い","相手の回答見込み","自分の最終確認日","再確認日"],"proposal":"提案：「返事が来た、でも揃った？」。質問を小項目に分け、受信した事実と項目別の回答済みを分離。必要項目が揃った工程だけ着手候補に戻し、部分回答は残る問いだけを手動文面へまとめる。\n統合した関連工程：提案：「相手の回答予定と自分の限界日」。相手が伝えた回答見込み、自分が次工程を始めるための最終確認日、再確認する日を別欄で持つ。待ち延長で後工程の余白がなくなる時は相談候補を出す。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-263","title":"次に話せる時の質問束","group":"連絡","fields":["相手の仮ID","元案件ID","未解決の問い","締切","待っている後工程","元案件への回答反映"],"proposal":"提案：「次に話せる時の質問束」。同じ仮IDの相手へ聞く未解決の問いを案件横断で一時集約し、締切と待っている後工程を付ける。回答は元案件へ戻し、一部の返答で全案件を完了にしない。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-264","title":"前提と判断のひも","group":"段取り","fields":["前提","決定","後続作業","前提の変更","影響を確認する判断","外部予約文の見直し","取消の実確認"],"proposal":"提案：「前提が変わったら知らせる判断ひも」。手入力した仮定を決定と後続作業に結ぶ。仮定の変更を記録した時、再検討する決定だけ表示し、完了作業を勝手に戻さず影響確認の控えを作る。\n統合した関連工程：提案：予約文の前提リスト。予約日時と本文で述べる開催日・資料版などの参照カードを結び、手元で前提を変更すると予約済み文面を『要見直し』へ戻す。元サービスでの取消確認を残す。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。\n統合した関連工程：こもれび側の状態変更で実メールが止まったと表示しない。閉じた間の監視を約束しない。"},{"id":"DOT-265","title":"見送った理由と再開条件","group":"段取り","fields":["採用案","見送った案","当時の制約","選び直す条件","今回違う条件"],"proposal":"提案：「選ばなかった理由と再開条件」。決定に採用案・見送った案・当時の制約・選び直す条件を残す。似た選択を始めた時は前回を参考表示し、条件が違えば新規判断として扱う。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-266","title":"今決めるか待って学ぶか","group":"段取り","fields":["やり直し費用","追加情報が届く日","実行に必要な時間","判断期限","小さく試す案","保留案"],"proposal":"提案：「今決める・待って学ぶ」。決定のやり直し費用、追加情報が届く日、実行に必要な時間、本人設定の判断期限を並べる。仮決めして小さく試す案と保留案を比較し、約束は人が確定する。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-267","title":"月ごとの未実施を残す","group":"段取り","fields":["対象年月ID","実施済み・不要確認・未実施","今回だけ休止の理由","振替要否","再開する回","元の周期"],"proposal":"提案：「月ごとの未実施を消さない」。定期作業は対象年月IDを持ち、実施済み・不要と確認・未実施を独立保存。今月を作成しても先月分を消さず、まとめて処理した場合もどの回が済んだか本人が選ぶ。\n統合した関連工程：提案：「今回は不要、次は戻す」。特定回だけの休止理由・振替要否・再開する回を保持する。未実施と意図した省略を分け、元の周期は変えず、ツールを開いた時に通常手順へ戻る予定を確認する。\n統合した関連工程：提案：「回をまたいで持ち越すものの指定」。定期手順で毎回確認する項目と初回だけの準備を区別し、次回生成前にリセットされる項目・残す設定・追加された手順をプレビュー。過去回の実施記録は上書きしない。\n統合した関連工程：提案：実行回つき作業つなぎ。各回に『メールで材料確認→表へ転記→別台帳照合』の短い工程IDを生成し、毎回必要／今回だけ／今回は不要を選ぶ。前回の完了は新しい回に継承しない。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。\n統合した関連工程：各工程の自動操作をしない。機微な原データは保持せず架空IDで設計。"},{"id":"DOT-268","title":"作業前に要る準備の束","group":"段取り","fields":["対象作業","必要資料群","机上準備","立上げ時間","一緒にできる作業","順番別の準備回数"],"proposal":"提案：「作業より先に必要な準備の束」。作業に必要な資料群・机上準備・本人入力の立上げ時間を結ぶ。同じ準備でできる作業を手動で束ね、順番を変えた場合の準備回数だけ比較する。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-269","title":"予定外も今日の仕事","group":"休息","fields":["割込みの種別","大まかな時間","延期した作業","通常仕事の配分","応答仕事の配分","翌週の応答枠"],"proposal":"提案：「予定外も今日の仕事」。割込みを詳細監視せず種別・大まかな時間・代わりに延期した作業だけ記録。週末に通常仕事と応答仕事の配分を本人が振り返り、翌週の仮の応答枠へ反映する。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-270","title":"全部を直さない再整理","group":"休息","fields":["控えへ置く項目","実害のある期限","他者への約束","まだ望むこと","元の期限","変更理由","今日へ戻す少数"],"proposal":"提案：「全部を直さない再整理」。古い項目を消さず控えへ置き、実害がある期限・他者への約束・まだ望むことだけを一件ずつ確かめる。元の期限と変更理由を保持し、今日へ戻す少数以外は未判断のまま残す。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。"},{"id":"DOT-271","title":"誰と決めた日付か","group":"段取り","fields":["日付の原文","自分の目安・希望・合意・外部締切","確認元","変更案","再確認が必要な相手","出力で落ちる意味"],"proposal":"提案：「その日付は誰と決めた？」。日付に自分の目安・相手の希望・合意済み・外部締切と確認元を付ける。変更操作時は根拠別に再確認が必要か表示し、日付の移動と合意の変更を別記録にする。\n統合した関連工程：提案：日付意味の引継ぎ札。『自分の着手予定／相手への約束／受付終了』を原文と分け、出力先に日付欄が一つなら何を入れ、何が落ちるか本人が選ぶ。","boundary":"業務の機密は持込規則を確認し、仮ID・所在メモを優先。入力は任意。送信・予定変更を自動実行しない。 ローカル単独利用。自動同期・バックグラウンド通知は前提にしない。R54/55解消と独立検証前は架空データのみ。\n統合した関連工程：原文の期限を勝手に緩めない。法的期限・時差の正確性は利用者が原文確認。"},{"id":"DOT-272","title":"会話の分岐目次","group":"連絡","fields":["案件ID","旧件名","新件名","別ソフトの参照先","分岐理由","次に確認する原文"],"proposal":"提案：会話の分岐目次。案件IDに旧件名・新件名・別ソフトの参照先、分岐理由と『次に確認する原文』を手入力で結び、全文を集めず会話の続きへ戻る。","boundary":"本文・認証情報を保存せず別名と所在だけで使う。リンクを自動巡回しない。"},{"id":"DOT-273","title":"共有受信箱の持帰り票","group":"連絡","fields":["原文の所在","箱の役割名","自分が引受けた部分","共有側へ戻す状態","自分の完了","共有側反映の確認"],"proposal":"提案：共有受信箱からの持帰り票。原メールの所在、箱の役割名、自分が引き受けた部分、戻すべき共有側の状態を対にし、自分の完了と元の箱への反映確認を分ける。","boundary":"他者のメールを無断複製しない。共同編集・担当の自動割当て・返信送信はしない。"},{"id":"DOT-274","title":"添付の受渡し照合","group":"連絡","fields":["添付のあるメッセージ所在","今回必要か不要か","渡す版","送信後の実添付確認","今回渡していないもの"],"proposal":"提案：会話の添付受渡し表。各添付のあるメッセージ、今回必要／不要、渡す版、送信後に人が確認した実添付を対応付ける。『前の会話にある』と『今回渡した』を分ける。","boundary":"不要な過去添付の一括転送を勧めない。実データ保存・自動送信はしない。"},{"id":"DOT-275","title":"役割別の送信前確認","group":"連絡","fields":["差出人の役割","返答を受ける箱の役割","署名の役割","三つの一致","確認した文面"],"proposal":"提案：役割別送信前カード。案件で使う差出人の役割、返答を受ける箱、署名の役割を並べ、作成した文面をコピーする前に三つの一致を確認する。実アドレスは任意。","boundary":"メール資格情報・SMTP設定は保持しない。匿名性や誤送信防止を保証しない。"},{"id":"DOT-276","title":"再接続後確認付き下書き","group":"連絡","fields":["文面の下書き","最新返答を読む条件","添付の確認条件","解放条件の手動確認","コピーした版"],"proposal":"提案：再接続後確認つき下書き置場。ローカルで文面を保留し、『最新返答を読む／添付を確認する』等の解放条件を手動確認してからコピーできる。外部送信トレイに入れる操作とは分ける。","boundary":"このツールから直接メールを送らない。本文は任意で仮名・要点のみでも使える。"},{"id":"DOT-277","title":"予定コピーの鮮度","group":"段取り","fields":["元カレンダー","取得日","対象期間","ローカルの編集","追加候補","変更候補","見当たらない予定"],"proposal":"提案：予定コピーの鮮度札。元カレンダー・取得日・対象期間とローカルの編集を分け、再取込時は追加／変更候補／見当たらない予定を比較して人が採否を決める。","boundary":"見当たらない予定を自動削除しない。取得範囲外と取消を区別する。"},{"id":"DOT-278","title":"会議取込の不足確認","group":"連絡","fields":["会議の時刻","主催者の確認元","参加方法の所在","招待承諾の手動確認","準備待ちの項目"],"proposal":"提案：会議取込の不足袋。時刻とは別に主催者の確認元、参加方法の所在、招待承諾を人が確認したかを持ち、空欄の会議だけを参加準備待ちへ出す。","boundary":"会議パスコード等は保存必須にしない。招待者へ自動連絡・再招待しない。"},{"id":"DOT-279","title":"日時の原文と換算","group":"段取り","fields":["短い日時の原文","相手が示した地域","相手の日付","確認した換算結果","固定か現地時刻か","双方の曜日"],"proposal":"提案：日時の原文札。原文の短い日時、相手が明示した地域・日付、自分が確認した換算結果、固定時刻／現地時刻の意図を併記。転記後は両者の曜日と日付を並べる。","boundary":"曖昧な略称を勝手に確定しない。旅行・金融等の重要期限は原サービスで確認。"},{"id":"DOT-280","title":"繰返しの一回変更","group":"段取り","fields":["系列ID","元の繰返し説明","対象回","変更した側","両画面で確認した日時","例外","今回か今後か"],"proposal":"提案：一回だけ変更の照合箱。系列ID・対象回・どちら側で変えたか・両画面で確認した日時を対にし、例外回だけ手動確認待ちとして残す。\n統合した関連工程：提案：反復の親子控え。系列ID・元の繰返し説明・各回の例外を別欄で保持し、CSV出力時に系列情報が落ちることを示す。変更相談時に今回分と今後分を分けた確認票を作る。","boundary":"外部同期が完了したと推定しない。確認時刻は本人の手動入力と表示。\n統合した関連工程：例外を勝手に系列全体へ適用しない。外部予定を変更しない。"},{"id":"DOT-281","title":"取下げと残る通知","group":"段取り","fields":["表示を隠す・作業不要・原文削除の意図","関連する場所","残存状態","通知の理由","外部通知の見直し","手動確認"],"proposal":"提案：取り下げ伝播票。『表示だけ消す／作業不要にする／原文を削除する』を先に選び、関連する各サービスの残存状態を手動照合する。操作名ではなく意図を残す。\n統合した関連工程：提案：通知の理由ひも付け。用件IDに『返答がなければ確認』などの理由と通知を置いた場所だけを登録。用件を完了・中止にしたら、残る外部通知を手動見直し候補へ出す。","boundary":"削除・取消は実行しない。元データがないことを完了・不要と自動判定しない。\n統合した関連工程：外部通知を自動削除しない。こもれびを閉じた間の通知検出・停止はできると表示しない。"},{"id":"DOT-282","title":"今日一覧に含む範囲","group":"段取り","fields":["一覧の所在","含むもの","含まないもの","別の入口","未確認","件数ゼロを確認した範囲"],"proposal":"提案：今日の一覧の収録範囲札。『この一覧には会議を含まない』等の確認済み境界を登録し、朝の確認では未確認の別入口だけを並べる。件数ゼロと未確認を区別する。","boundary":"未接続の情報を取得済みと表示しない。監視や常駐通知は約束しない。"},{"id":"DOT-283","title":"作業枠と外からの予約状態","group":"段取り","fields":["自分の作業予定","周囲からの予約不可確認","外から空いて見える枠","再確認日"],"proposal":"提案：作業枠の二重状態。本人の作業予定と、周囲から見た予約不可確認を別欄にし、『自分では埋まっているが外から空いて見える枠』だけを確認候補にする。","boundary":"他者の招待を自動拒否しない。予定非公開・勤務監視機能として扱わない。"},{"id":"DOT-284","title":"片付けの意図と原本","group":"データ","fields":["一覧から隠す・容量を空ける・原本をなくす","対象が原本・コピー・参照のどれか","公式手順の確認日","人の判断"],"proposal":"提案：片付け意図の確認札。『自分の一覧から隠す／端末容量だけ空ける／原本をなくす』を選び、対象が原本・コピー・参照のどれかと公式手順の確認日を並べる。削除は実行しない。","boundary":"操作指示の自動実行をせず、削除安全の保証もしない。分からない対象は保留。"},{"id":"DOT-285","title":"端末別の持出し準備","group":"データ","fields":["会議や作業","資料の所在","使う端末","オフライン実開封日","編集可否","不足分"],"proposal":"提案：端末別の持出し一式票。会議・作業ごとに必要な資料の所在、使用端末、オフライン実開封日、編集可否を対応付け、不足分だけを出発前に確認する。","boundary":"無許可の持出しを勧めない。実体をこもれびへ埋め込まない。保存済み保証はしない。"},{"id":"DOT-286","title":"編集する場所の案内","group":"データ","fields":["リンク部品","数値の原本","表現を変えた側","残したい局所変更","失うかもしれない変更","戻すか分岐するか"],"proposal":"提案：編集する場所の案内札。リンク部品ごとに数値の原本、表現を変えた側、残したい局所変更を記録。更新前に『失うかもしれない変更』を確認し、元側へ戻すか静的に分岐するか人が選ぶ。","boundary":"変更を必ず保全できると保証しない。実ファイルの更新やリンク解除は自動実行しない。"},{"id":"DOT-287","title":"相談付きコピーの分岐","group":"データ","fields":["親文書ID","子文書ID","未決論点ID","相談を続ける側","旧側の参照専用案内","持込まない議論"],"proposal":"提案：相談つきコピーの分岐票。親文書・子文書、引き継いだ未決論点ID、どちらで相談を続けるか、旧側を参照専用と案内したかを保持。新しい版へ持ち込まない議論も明示する。","boundary":"参加者の同意なく旧コメントを閉じない。本文・コメントの一括コピーを必須にしない。"}];
